import{d as K,C as g,o as v,c as B,j as e,a as d,E as a,a3 as n,k as l}from"./chunks/framework.Q4yG9rk_.js";const F=JSON.parse('{"title":"庄子·渔父","description":"从林中相遇与孔子追寻求教开始，逐步辨析职分、疵患、修身守真及尊贤尊道。第一节整理至“无所得闻至教，敢不虚心”。","frontmatter":{"title":"庄子·渔父","description":"从林中相遇与孔子追寻求教开始，逐步辨析职分、疵患、修身守真及尊贤尊道。第一节整理至“无所得闻至教，敢不虚心”。","category":"庄子精读","aliases":["渔父","庄子渔父","庄子·渔父精读"],"source":["《庄子·杂篇·渔父》","用户提供的《渔父》原文与分段整理材料"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-31.md","filePath":"daoism/zhuang-zi/chapter-31.md","lastUpdated":1792646839000}'),G={name:"daoism/zhuang-zi/chapter-31.md"},J=K({...G,setup(O){const h=[{id:"yf-yufu",term:"渔父",pinyin:"yú fǔ",meaning:"打鱼的年长男子。“父”在此是对老者的称谓。"},{id:"yf-ziwei",term:"缁帷之林",pinyin:"zī wéi zhī lín",meaning:"林名或场景名称。“缁帷”字面为黑色帷幕，不据此强定实际地点。"},{id:"yf-xingtan",term:"杏坛",pinyin:"xìng tán",meaning:"此处为孔子休坐、弦歌的坛地；具体形貌与历史地点不在本段补定。"},{id:"yf-xiange",term:"弦歌鼓琴",pinyin:"",meaning:"弹琴并歌唱。“鼓”在此是弹奏之义。"},{id:"yf-xumei",term:"须眉交白",pinyin:"",meaning:"胡须、眉毛都已发白。"},{id:"yf-pifa",term:"被发",pinyin:"pī fà",meaning:"披散头发。“被”通“披”。"},{id:"yf-yumei",term:"揄袂",pinyin:"yú mèi",meaning:"提起、扬起衣袖。"},{id:"yf-xingyuan",term:"行原以上",pinyin:"",meaning:"基本语意可联系沿岸边高地向上行理解，“以”联系“而”理解；具体空间层次有训释差异。"},{id:"yf-julu",term:"距陆而止",pinyin:"",meaning:"基本语意为到陆地、岸上停下；“距”及岸地层次的具体训释有讨论空间。"},{id:"yf-juxi",term:"据膝",pinyin:"",meaning:"手按、倚着膝部。"},{id:"yf-chiyi",term:"持颐",pinyin:"chí yí",meaning:"托着下巴。"},{id:"yf-judui",term:"俱对",pinyin:"",meaning:"两人一同前来答话。"},{id:"yf-ke",term:"客",pinyin:"",meaning:"叙事中对渔父的称呼，不必理解为孔子原有的宾客。"},{id:"yf-zu",term:"族",pinyin:"",meaning:"家族、氏族；这里回答为孔氏。"},{id:"yf-hezhi",term:"何治",pinyin:"",meaning:"从事、经营什么，所致力者是什么。"},{id:"yf-xingfu",term:"性服忠信",pinyin:"",meaning:"本性服膺忠信，把忠信作为所遵行的准则。"},{id:"yf-shili",term:"饰礼乐",pinyin:"",meaning:"修治、整饬礼乐。“饰”不宜在此直接译成虚假的装饰。"},{id:"yf-xuanrenlun",term:"选人伦",pinyin:"",meaning:"分辨、厘定人伦关系；“选”不只作挑选人员解。"},{id:"yf-shizhu",term:"世主",pinyin:"",meaning:"当世的君主。"},{id:"yf-qimin",term:"齐民",pinyin:"",meaning:"一般民众、百姓。"},{id:"yf-youtuzhijun",term:"有土之君",pinyin:"",meaning:"拥有封土、统治一方的君主。"},{id:"yf-houwangzhizuo",term:"侯王之佐",pinyin:"",meaning:"辅佐侯王的臣属。"},{id:"yf-huanxing",term:"还行",pinyin:"",meaning:"转身离去。“还”联系回转理解。"},{id:"yf-bumian",term:"不免其身",pinyin:"",meaning:"自身恐不能免于祸患、伤害。"},{id:"yf-kuxin",term:"苦心劳形",pinyin:"",meaning:"使心神劳苦，使身体疲劳。"},{id:"yf-weiqizhen",term:"危其真",pinyin:"",meaning:"危及自身之真。“真”的具体内容须留待后文“何谓真”的问答展开。"},{id:"yf-fenyudao",term:"分于道",pinyin:"",meaning:"与道分离、相距甚远。"},{id:"yf-qishengren",term:"其圣人与",pinyin:"",meaning:"莫非是圣人吗？“其”含推测语气，“与”通“欤”。这是孔子的推测，不是叙述者直接确认。"},{id:"yf-zepan",term:"泽畔",pinyin:"zé pàn",meaning:"水泽岸边。"},{id:"yf-zhangna",term:"杖拏",pinyin:"zhàng ná",meaning:"持桨、用桨。“拏”指船桨。"},{id:"yf-yinchuan",term:"引其船",pinyin:"",meaning:"引动船只，准备离岸。"},{id:"yf-gu",term:"顾",pinyin:"",meaning:"回头看。"},{id:"yf-huanxiang",term:"还乡",pinyin:"",meaning:"转过身来，面向孔子。“乡”通“向”。"},{id:"yf-fanzou",term:"反走",pinyin:"",meaning:"退步趋行一类的恭敬动作，具体动作有训释差异。“走”为快步行，不作逃跑解。"},{id:"yf-zaibai",term:"再拜",pinyin:"",meaning:"拜两次，表示郑重敬意。"},{id:"yf-nangzhe",term:"曩者",pinyin:"nǎng zhě",meaning:"刚才、先前。"},{id:"yf-xuyan",term:"绪言",pinyin:"",meaning:"开端之言、尚未充分展开的话。"},{id:"yf-buxiao",term:"不肖",pinyin:"bù xiào",meaning:"自称不才、不贤的谦辞。"},{id:"yf-xiafeng",term:"下风",pinyin:"",meaning:"谦称处于对方之下，等待指教。"},{id:"yf-ketuo",term:"咳唾之音",pinyin:"",meaning:"以对方咳嗽、吐唾的声音谦指其言语，表示愿闻教诲，不按字面理解为只求听咳嗽声。"},{id:"yf-zuxiang",term:"卒相丘",pinyin:"",meaning:"进一步、最终帮助我。“相”为帮助之义。"},{id:"yf-zhijiao",term:"至教",pinyin:"",meaning:"至高、深切的教诲。"},{id:"yf-ganbuxuxin",term:"敢不虚心",pinyin:"",meaning:"怎敢不虚心接受？以反问表示郑重求教。"},{id:"yf3-qiaoran",term:"愀然",pinyin:"qiǎo rán",meaning:"神色忧愁、肃然的样子。"},{id:"yf3-zaibai",term:"再拜",pinyin:"",meaning:"拜两次，表示郑重敬意。"},{id:"yf3-zaizhu",term:"再逐于鲁",pinyin:"",meaning:"两次被逐于鲁；此处“再”通常按两次理解。"},{id:"yf3-xiaoji",term:"削迹于卫",pinyin:"",meaning:"在卫国遭排斥、行迹受到阻绝一类遭遇；具体事件细节不在此补定。"},{id:"yf3-fashu",term:"伐树于宋",pinyin:"",meaning:"在宋国遭遇树木被砍伐之事，语境中属于受威胁的困厄。"},{id:"yf3-chencai",term:"围于陈蔡",pinyin:"",meaning:"在陈、蔡之间受围、受困。"},{id:"yf3-suoshi",term:"所失",pinyin:"",meaning:"自己失当、过失之所在。"},{id:"yf3-li",term:"离",pinyin:"",meaning:"通“罹”，遭遇、遭受。"},{id:"yf3-sibang",term:"四谤",pinyin:"",meaning:"结合本段，指前述四类困厄、毁伤；具体训释有空间，不宜只按现代“诽谤言论”理解。"},{id:"yf3-qiran",term:"凄然变容",pinyin:"",meaning:"神色转为悲伤、严肃；不只是发怒的表情。"},{id:"yf3-wu",term:"悟",pinyin:"wù",meaning:"领会、明白。"},{id:"yf3-weiying",term:"畏影恶迹",pinyin:"wèi yǐng wù jì",meaning:"害怕影子，厌恶脚印。“恶”读 wù。"},{id:"yf3-quzhizou",term:"去之走",pinyin:"",meaning:"为摆脱影子与脚印而奔跑。"},{id:"yf3-juzushu",term:"举足愈数",pinyin:"数：shuò",meaning:"抬脚、迈步越来越频繁。“数”为频繁之义。"},{id:"yf3-shangchi",term:"尚迟",pinyin:"",meaning:"仍然太慢。"},{id:"yf3-jueli",term:"绝力",pinyin:"",meaning:"力气耗尽。"},{id:"yf3-chuyin",term:"处阴",pinyin:"",meaning:"待在阴暗、荫蔽之处。"},{id:"yf3-xiuying",term:"休影",pinyin:"",meaning:"使影子止息、不再显现。"},{id:"yf3-chujing",term:"处静",pinyin:"",meaning:"静处、不再奔走。"},{id:"yf3-xiji",term:"息迹",pinyin:"",meaning:"停止产生新的脚印，不是抹去所有旧脚印。"},{id:"yf3-shen",term:"审",pinyin:"",meaning:"细察、审究。"},{id:"yf3-renyizhijian",term:"仁义之间",pinyin:"",meaning:"仁义之间的关系、分际等，具体所指有解释空间。"},{id:"yf3-tongyi",term:"同异之际",pinyin:"",meaning:"同与异的界限、交接之处。"},{id:"yf3-shouyu",term:"适受与之度",pinyin:"",meaning:"调整接受与给予的分寸。“适”有使之合宜之意。"},{id:"yf3-haowu",term:"好恶",pinyin:"hào wù",meaning:"喜好与厌恶。"},{id:"yf3-xinu",term:"和喜怒之节",pinyin:"",meaning:"调和喜怒，使其合乎节度。"},{id:"yf3-jiyubumian",term:"几于不免",pinyin:"jī yú bù miǎn",meaning:"接近不能免于祸患、伤害的境地。"},{id:"yf3-xiushen",term:"谨修而身",pinyin:"",meaning:"谨慎修治你自身。“而”通“尔”。"},{id:"yf3-shouzhen",term:"慎守其真",pinyin:"",meaning:"慎重守护自身之真；“真”的具体内容将在下一份展开。"},{id:"yf3-huanyi",term:"还以物与人",pinyin:"",meaning:"通常联系把外物、事务还给他人理解；具体“物”的范围及句法有分歧。"},{id:"yf3-lei",term:"累",pinyin:"lěi",meaning:"牵累、负担、困扰。"},{id:"yf3-qiuzhiren",term:"不修之身而求之人",pinyin:"",meaning:"不从自身修治，却向他人求取、着力于他人；不在此限定为只求名声、官位或认同。"},{id:"yf3-wai",term:"外",pinyin:"",meaning:"向外求取、着力外在，不只是空间上的外面。"},{id:"yf4-qiaoran",term:"愀然",pinyin:"qiǎo rán",meaning:"神色忧愁、肃然的样子。"},{id:"yf4-zhen",term:"真",pinyin:"zhēn",meaning:"本段以“精诚之至”说明，涉及内在精诚及其真实表现，不只指消息属实或没有说谎。"},{id:"yf4-jingcheng",term:"精诚",pinyin:"",meaning:"纯粹、专一而诚实，不夹杂勉强造作；“精”不只作精细解。"},{id:"yf4-zhi",term:"至",pinyin:"",meaning:"极致、充分达到。"},{id:"yf4-dongren",term:"动人",pinyin:"",meaning:"感动、感发他人，不只是引起注意。"},{id:"yf4-qiangku",term:"强哭",pinyin:"qiǎng kū",meaning:"勉强作哭。强为勉强之义；“强哭者，虽悲不哀”与下文强怒、强亲并举。"},{id:"yf4-qiangnu",term:"强怒",pinyin:"qiǎng nù",meaning:"勉强作怒。“强怒者，虽严不屯”，与强哭、强亲同列。"},{id:"yf4-beibuai",term:"虽悲不哀",pinyin:"",meaning:"虽有悲哭的形貌，却没有真实的哀感或不能感发哀感。"},{id:"yf4-yanbuzhun",term:"虽严不屯",pinyin:"",meaning:"虽显得严厉，却缺少真实怒意所带来的威势；“屯”的具体训释有差异，此处不强定读音与唯一解释。"},{id:"yf4-qin",term:"亲",pinyin:"",meaning:"亲近、亲爱，不只指亲属。"},{id:"yf4-he",term:"和",pinyin:"",meaning:"和悦、融洽。"},{id:"yf4-shendong",term:"神动于外",pinyin:"",meaning:"内在精神、情感感发于外，不必作超自然力量解。"},{id:"yf4-renli",term:"人理",pinyin:"",meaning:"人伦关系与人间事务的道理。"},{id:"yf4-cixiao",term:"慈孝",pinyin:"",meaning:"慈爱、孝敬。"},{id:"yf4-zhongzhen",term:"忠贞",pinyin:"",meaning:"忠诚、坚定；本段进一步以实际功效说明。"},{id:"yf4-gong",term:"功",pinyin:"",meaning:"事务的成就、实际功效，不只指个人功名。"},{id:"yf4-shi",term:"适",pinyin:"",meaning:"合宜，使所事之亲得到适宜的照料与安顿。"},{id:"yf4-wuyiqiji",term:"无一其迹",pinyin:"",meaning:"通常联系不把实现功成的行迹、方式限定为一种理解；具体字义与句法有训释空间。"},{id:"yf4-suoyi",term:"所以",pinyin:"",meaning:"所采用的办法、凭借的方式。"},{id:"yf4-ju",term:"具",pinyin:"",meaning:"器具、用具，语境中指饮酒所用之具等。"},{id:"yf4-wuwenqili",term:"无问其礼",pinyin:"",meaning:"不以特定礼仪形式作为判断的首要依据；应结合“处丧以哀”的语境理解。"},{id:"yf4-shouyutian",term:"受于天",pinyin:"",meaning:"禀受于天，联系天然所具、非人为矫饰理解。"},{id:"yf4-fatian",term:"法天",pinyin:"",meaning:"取法于天、自然。"},{id:"yf4-xuyuren",term:"恤于人",pinyin:"",meaning:"顾虑、迁就他人的看法；不宜在此只译为体恤他人。"},{id:"yf4-lulu",term:"禄禄",pinyin:"",meaning:"平庸、庸碌的样子。"},{id:"yf4-shoubian",term:"受变于俗",pinyin:"",meaning:"被世俗习惯改变、牵引。"},{id:"yf4-zaozhan",term:"蚤湛",pinyin:"zǎo zhàn",meaning:"很早便沉溺其中。“蚤”通“早”，“湛”联系沉浸理解。"},{id:"yf4-wei",term:"伪",pinyin:"",meaning:"人为造作、失真的表现，不只指蓄意欺骗。"},{id:"yf4-deyu",term:"得遇",pinyin:"",meaning:"得以遇见先生、获得这次受教的机会。"},{id:"yf4-tianxing",term:"天幸",pinyin:"",meaning:"仿佛上天给予的幸运。"},{id:"yf4-bizhifuyi",term:"比之服役",pinyin:"",meaning:"通常联系将自己置于可受教、可服役者之列理解；句法有训释空间。"},{id:"yf4-shenjiao",term:"身教之",pinyin:"",meaning:"亲自教导我，不宜只限于现代“以行动示范”的身教义。"},{id:"yf4-she",term:"舍",pinyin:"shè",meaning:"居处、住所。"},{id:"yf4-shouye",term:"受业",pinyin:"",meaning:"接受教导、学习。"},{id:"yf4-zuxue",term:"卒学",pinyin:"",meaning:"继续、完成所学。"},{id:"yf4-keyuwang",term:"可与往",pinyin:"",meaning:"可以一同前往、共同进于道。"},{id:"yf4-miaodao",term:"妙道",pinyin:"",meaning:"精微、深妙的道。"},{id:"yf4-bukeyuwang",term:"不可与往者，不知其道",pinyin:"",meaning:"具体句法与“不知”的主体有解释空间；结合下文，主要涉及辨别能否共同进于道，不强定为对孔子不可教的明确判决。"},{id:"yf4-jiu",term:"咎",pinyin:"jiù",meaning:"过失、祸患。"},{id:"yf4-lachuan",term:"剌船",pinyin:"",meaning:"撑船、划船。“剌”不要与“刺”字混同。"},{id:"yf4-yanyuan",term:"延缘苇间",pinyin:"",meaning:"沿着、循着芦苇间的水路而去。"},{id:"yf5-yanyuan",term:"颜渊",pinyin:"",meaning:"孔子弟子颜回，字子渊。"},{id:"yf5-huanche",term:"还车",pinyin:"",meaning:"转回、调转车子，准备离开。"},{id:"yf5-shousui",term:"授绥",pinyin:"绥：suí",meaning:"将登车所用的绳带递给孔子。“绥”为上车时可以攀援的绳索、带子。"},{id:"yf5-bugu",term:"不顾",pinyin:"",meaning:"不回顾、不理会眼前的登车安排；不必理解为故意轻慢弟子。"},{id:"yf5-nayin",term:"拏音",pinyin:"ná yīn",meaning:"船桨划水的声音。"},{id:"yf5-pangche",term:"旁车",pinyin:"",meaning:"在车旁。"},{id:"yf5-you",term:"由",pinyin:"",meaning:"子路名仲由，此处为自称。"},{id:"yf5-weiyi",term:"为役",pinyin:"",meaning:"随侍、为夫子服务，是弟子的自谦表达。"},{id:"yf5-wei",term:"如此其威",pinyin:"",meaning:"在此通常联系敬畏、肃敬理解，不是孔子向渔父施威；具体词义须结合上下文。"},{id:"yf5-wancheng",term:"万乘",pinyin:"wàn shèng",meaning:"以兵车数量表示君主的权势与国力。乘为兵车单位。"},{id:"yf5-qiancheng",term:"千乘",pinyin:"qiān shèng",meaning:"与万乘并列，指次一等的国力等级。"},{id:"yf5-fenting",term:"分庭伉礼",pinyin:"",meaning:"分庭相见，以相抗、相当的礼节交往。“伉”联系“抗”理解。"},{id:"yf5-juao",term:"倨傲",pinyin:"jù ào",meaning:"高倨、不屈就的样子；此处是子路对孔子姿态的描述。"},{id:"yf5-zhangna",term:"杖拏逆立",pinyin:"",meaning:"持桨迎面站立。“逆”为迎接之义，不作反抗解。"},{id:"yf5-quyao",term:"曲要",pinyin:"qū yāo",meaning:"弯腰。“要”通“腰”。"},{id:"yf5-qingzhe",term:"磬折",pinyin:"qìng zhé",meaning:"屈身如磬的弯折形状，形容郑重恭敬。"},{id:"yf5-yanbai",term:"言拜而应",pinyin:"",meaning:"在问答中拜而回应，突出应答的恭敬姿态。"},{id:"yf5-dewu",term:"得无太甚乎",pinyin:"",meaning:"莫非太过分了吗？表示疑问与保留。"},{id:"yf5-guai",term:"怪",pinyin:"",meaning:"感到奇怪、不能理解。"},{id:"yf5-fushi",term:"伏轼",pinyin:"",meaning:"俯身凭倚车前的横木。"},{id:"yf5-hua",term:"化",pinyin:"",meaning:"转变、受教而改变，不只指记住知识。"},{id:"yf5-zhanyu",term:"湛于礼义",pinyin:"",meaning:"沉浸、浸习于礼义。"},{id:"yf5-youjian",term:"有间",pinyin:"",meaning:"已有一段时间、相当久。"},{id:"yf5-pubi",term:"朴鄙",pinyin:"",meaning:"粗陋、见识未开。“朴”在此不作值得赞许的质朴解。"},{id:"yf5-zhang",term:"长",pinyin:"zhǎng",meaning:"年长者。"},{id:"yf5-zhiren",term:"至人",pinyin:"",meaning:"修养、境界达到高度的人，不只指身份尊贵者。"},{id:"yf5-xiaren",term:"下人",pinyin:"",meaning:"谦下于人，能够降低自居的姿态、尊重他人；不指地位低的人。"},{id:"yf5-bujing",term:"不精",pinyin:"",meaning:"不精诚、不纯粹，谦下中仍夹杂造作等。"},{id:"yf5-changshang",term:"长伤身",pinyin:"",meaning:"通常联系长久、常常伤害自身理解。“长”在此联系时间延续，与“遇长”的“长”不同。"},{id:"yf5-shanzhi",term:"擅之",pinyin:"",meaning:"独有、专有此患，是责叹中的强调，不必按统计事实理解。"},{id:"yf5-suoyou",term:"万物之所由",pinyin:"",meaning:"万物所由以运行、发生的根据或道路。"},{id:"yf5-shuwu",term:"庶物",pinyin:"",meaning:"众物、各种事物与生命。"},{id:"yf5-youyudao",term:"于道，可谓有矣",pinyin:"",meaning:"在道上可说有所获得、有所得。这是孔子对渔父的评价。"},{id:"yf2-tianzhili",term:"天之理",pinyin:"tiān zhī lǐ",meaning:"自然的条理。渔父以此为自己进言的依据，不是凭权威压人。"},{id:"yf2-shisuo",term:"释吾所有",pinyin:"shì wú suǒ yǒu",meaning:"把我所懂的讲清楚。释为陈说、解释。「释吾所有」连读。"},{id:"yf2-jingzi",term:"经子之所以",pinyin:"jīng zǐ zhī suǒ yǐ",meaning:"条理你所作所为。经为经营、条理；「所以」指所做的事。"},{id:"yf2-sizhe",term:"四者自正",pinyin:"sì zhě zì zhèng",meaning:"天子、诸侯、大夫、庶人四类各安其位。与「四者离位」对举。"},{id:"yf2-liwei",term:"离位",pinyin:"lí wèi",meaning:"离开本位、越出职分。乱由此生，不是职位本身有罪。"},{id:"yf2-wusuoling",term:"无所陵",pinyin:"wú suǒ líng",meaning:"不相侵越。陵为凌驾、侵陵。"},{id:"yf2-tianhuang",term:"田荒室露",pinyin:"tián huāng shì lù",meaning:"田地荒芜、屋室破败。庶人之忧的第一项。"},{id:"yf2-zhengfu",term:"征赋不属",pinyin:"zhēng fù bù shǔ",meaning:"赋税不能按时缴纳。属为连属、接续。"},{id:"yf2-changshao",term:"长少无序",pinyin:"zhǎng shào wú xù",meaning:"长幼失序。与衣食、赋税、妻妾并列，都是家里的实情。"},{id:"yf2-bushengren",term:"能不胜任",pinyin:"néng bù shèng rèn",meaning:"能力担不起职任。大夫之忧的第一项。"},{id:"yf2-qingbai",term:"行不清白",pinyin:"xíng bù qīng bái",meaning:"操行不清白。"},{id:"yf2-juelu",term:"爵禄不持",pinyin:"jué lù bù chí",meaning:"爵位俸禄保不住。持为守。"},{id:"yf2-houlun",term:"春秋后伦",pinyin:"chūn qiū hòu lún",meaning:"朝聘失序、落在同列之后。诸侯之忧的一项。"},{id:"yf2-yinyang",term:"阴阳不和",pinyin:"yīn yáng bù hé",meaning:"阴阳失调、寒暑不时。天子有司之忧的第一项。"},{id:"yf2-caiyong",term:"财用穷匮",pinyin:"cái yòng qióng kuì",meaning:"财用匮乏。与礼乐、人伦并列。"},{id:"yf2-renlun",term:"人伦不饬",pinyin:"rén lún bù chì",meaning:"人伦不整饬。饬为整、治。"},{id:"yf2-shanshi",term:"擅饰礼乐",pinyin:"shàn shì lǐ yuè",meaning:"擅自修治礼乐。擅为专擅，正是被质疑处。"},{id:"yf2-xuanrenlun",term:"选人伦",pinyin:"xuǎn rén lún",meaning:"简择、条理人伦。选为择治，不作「挑选人才」解。"},{id:"yf2-huaqimin",term:"化齐民",pinyin:"huà qí mín",meaning:"教化齐一百姓。齐为齐同，不是「齐国之人」。"},{id:"yf2-taiduos",term:"不泰多事",pinyin:"bù tài duō shì",meaning:"岂不是太多事。泰通「太」；此为反问，非断语。"},{id:"yf2-baci",term:"八疵",pinyin:"bā cī",meaning:"八种行为上的毛病。疵为病、缺陷，指待人接物的失当。"},{id:"yf2-sihuan",term:"四患",pinyin:"sì huàn",meaning:"四种办事上的患害。与八疵分列：一在待人，一在任事。"},{id:"yf2-zong",term:"摠",pinyin:"zǒng",meaning:"非己事而揽来去做。通「总」，此处为贬义。"},{id:"yf2-ning",term:"佞",pinyin:"nìng",meaning:"人不理会而硬要进言。"},{id:"yf2-chan",term:"谄",pinyin:"chǎn",meaning:"揣度人意、顺着说好话。"},{id:"yf2-yu",term:"谀",pinyin:"yú",meaning:"不辨是非一味奉承。与「谄」相近而更泛。"},{id:"yf2-chan2",term:"谗",pinyin:"chán",meaning:"好说别人坏话。"},{id:"yf2-zei",term:"贼",pinyin:"zéi",meaning:"挑拨离间、拆人交谊。不作盗贼解。"},{id:"yf2-te",term:"慝",pinyin:"tè",meaning:"以称誉诈伪败坏他人。慝为邪、恶。"},{id:"yf2-xian",term:"险",pinyin:"xiǎn",meaning:"两面讨好、暗中抽取自己所想要的。八疵中最后一项。"},{id:"yf2-tao",term:"叨",pinyin:"tāo",meaning:"好揽大事、变更常规以博功名。四患第一项。"},{id:"yf2-tan",term:"贪",pinyin:"tān",meaning:"专断自用、侵夺他人。贪在此指权与事的独占。"},{id:"yf2-hen",term:"很",pinyin:"hěn",meaning:"见过不改、闻谏更甚。很通「狠」，刚愎。"},{id:"yf2-jin",term:"矜",pinyin:"jīn",meaning:"只认同自己、以己为高。四患最后一项。"},{id:"yf2-shikejiao",term:"始可教",pinyin:"shǐ kě jiào",meaning:"然后才可以教。渔父把「去八疵、无行四患」列为受教前提。"}],b=[{id:"yufu-p1-01",label:"林中弦歌",sentences:[["孔子游乎",{text:"缁帷之林",glossary:"yf-ziwei"},"，休坐乎",{text:"杏坛",glossary:"yf-xingtan"},"之上。"],["弟子读书，孔子",{text:"弦歌鼓琴",glossary:"yf-xiange"},"。"]]},{id:"yufu-p1-02",label:"渔父来听",sentences:[["奏曲未半，有",{text:"渔父",glossary:"yf-yufu"},"者，下船而来，",{text:"须眉交白",glossary:"yf-xumei"},"，",{text:"被发",glossary:"yf-pifa"},{text:"揄袂",glossary:"yf-yumei"},"，",{text:"行原以上",glossary:"yf-xingyuan"},"，",{text:"距陆而止",glossary:"yf-julu"},"，左手",{text:"据膝",glossary:"yf-juxi"},"，右手",{text:"持颐",glossary:"yf-chiyi"},"以听。"],["曲终而招子贡、子路二人",{text:"俱对",glossary:"yf-judui"},"。"]]},{id:"yufu-p1-03",label:"询问身份",sentences:[[{text:"客",glossary:"yf-ke"},"指孔子曰：“彼何为者也？”子路对曰：“鲁之君子也。”"],["客问其",{text:"族",glossary:"yf-zu"},"。子路对曰：“族孔氏。”"],["客曰：“孔氏者",{text:"何治",glossary:"yf-hezhi"},"也？”"]]},{id:"yufu-p1-04",label:"子贡述志",sentences:[["子路未应，子贡对曰：“孔氏者，",{text:"性服忠信",glossary:"yf-xingfu"},"，身行仁义，",{text:"饰礼乐",glossary:"yf-shili"},"，",{text:"选人伦",glossary:"yf-xuanrenlun"},"。"],["上以忠于",{text:"世主",glossary:"yf-shizhu"},"，下以化于",{text:"齐民",glossary:"yf-qimin"},"，将以利天下。此孔氏之所治也。”"]]},{id:"yufu-p1-05",label:"追问位置",sentences:[["又问曰：“",{text:"有土之君",glossary:"yf-youtuzhijun"},"与？”子贡曰：“非也。”"],["“",{text:"侯王之佐",glossary:"yf-houwangzhizuo"},"与？”子贡曰：“非也。”"]]},{id:"yufu-p1-06",label:"初次批评",sentences:[["客乃笑而",{text:"还行",glossary:"yf-huanxing"},"，言曰：“仁则仁矣，恐",{text:"不免其身",glossary:"yf-bumian"},"。"],[{text:"苦心劳形",glossary:"yf-kuxin"},"以",{text:"危其真",glossary:"yf-weiqizhen"},"。呜呼！远哉，其",{text:"分于道",glossary:"yf-fenyudao"},"也。”"]]},{id:"yufu-p1-07",label:"孔子追寻",sentences:[["子贡还，报孔子。孔子推琴而起，曰：“",{text:"其圣人与",glossary:"yf-qishengren"},"？”乃下求之，至于",{text:"泽畔",glossary:"yf-zepan"},"。"],["方将",{text:"杖拏",glossary:"yf-zhangna"},"而",{text:"引其船",glossary:"yf-yinchuan"},"，",{text:"顾",glossary:"yf-gu"},"见孔子，",{text:"还乡",glossary:"yf-huanxiang"},"而立。"],["孔子",{text:"反走",glossary:"yf-fanzou"},"，",{text:"再拜",glossary:"yf-zaibai"},"而进。"]]},{id:"yufu-p1-08",label:"请求展开",sentences:[["客曰：“子将何求？”"],["孔子曰：“",{text:"曩者",glossary:"yf-nangzhe"},"先生有",{text:"绪言",glossary:"yf-xuyan"},"而去，丘",{text:"不肖",glossary:"yf-buxiao"},"，未知所谓，窃待于",{text:"下风",glossary:"yf-xiafeng"},"，幸闻",{text:"咳唾之音",glossary:"yf-ketuo"},"，以",{text:"卒相丘",glossary:"yf-zuxiang"},"也。”"]]},{id:"yufu-p1-09",label:"虚心受教",sentences:[["客曰：“嘻！甚矣，子之好学也！”"],["孔子再拜而起，曰：“丘少而修学，以至于今，六十九岁矣，无所得闻",{text:"至教",glossary:"yf-zhijiao"},"，",{text:"敢不虚心",glossary:"yf-ganbuxuxin"},"！”"]]},{id:"yufu-p3-01",label:"困厄追问",sentences:[["孔子",{text:"愀然",glossary:"yf3-qiaoran"},"而叹，",{text:"再拜",glossary:"yf3-zaibai"},"而起，曰：“丘",{text:"再逐于鲁",glossary:"yf3-zaizhu"},"，",{text:"削迹于卫",glossary:"yf3-xiaoji"},"，",{text:"伐树于宋",glossary:"yf3-fashu"},"，",{text:"围于陈蔡",glossary:"yf3-chencai"},"。"],["丘不知",{text:"所失",glossary:"yf3-suoshi"},"，而",{text:"离",glossary:"yf3-li"},"此",{text:"四谤",glossary:"yf3-sibang"},"者何也？”"]]},{id:"yufu-p3-02",label:"畏影恶迹",sentences:[["客",{text:"凄然变容",glossary:"yf3-qiran"},"曰：“甚矣，子之难",{text:"悟",glossary:"yf3-wu"},"也！"],["人有",{text:"畏影恶迹",glossary:"yf3-weiying"},"而",{text:"去之走",glossary:"yf3-quzhizou"},"者，",{text:"举足愈数",glossary:"yf3-juzushu"},"而迹愈多，走愈疾而影不离身，自以为",{text:"尚迟",glossary:"yf3-shangchi"},"，疾走不休，",{text:"绝力",glossary:"yf3-jueli"},"而死。"]]},{id:"yufu-p3-03",label:"处阴处静",sentences:[["不知",{text:"处阴",glossary:"yf3-chuyin"},"以",{text:"休影",glossary:"yf3-xiuying"},"，",{text:"处静",glossary:"yf3-chujing"},"以",{text:"息迹",glossary:"yf3-xiji"},"，愚亦甚矣！"]]},{id:"yufu-p3-04",label:"细密经营",sentences:[["子",{text:"审",glossary:"yf3-shen"},{text:"仁义之间",glossary:"yf3-renyizhijian"},"，察",{text:"同异之际",glossary:"yf3-tongyi"},"，观动静之变，",{text:"适受与之度",glossary:"yf3-shouyu"},"，理",{text:"好恶",glossary:"yf3-haowu"},"之情，",{text:"和喜怒之节",glossary:"yf3-xinu"},"，而",{text:"几于不免",glossary:"yf3-jiyubumian"},"矣。"]]},{id:"yufu-p3-05",label:"修身守真",sentences:[[{text:"谨修而身",glossary:"yf3-xiushen"},"，",{text:"慎守其真",glossary:"yf3-shouzhen"},"，",{text:"还以物与人",glossary:"yf3-huanyi"},"，则无所",{text:"累",glossary:"yf3-lei"},"矣。"],["今",{text:"不修之身而求之人",glossary:"yf3-qiuzhiren"},"，不亦",{text:"外",glossary:"yf3-wai"},"乎！”"]]},{id:"yufu-p4-01",label:"追问与定义",sentences:[["孔子",{text:"愀然",glossary:"yf4-qiaoran"},"曰：“请问何谓",{text:"真",glossary:"yf4-zhen"},"？”"],["客曰：“真者，",{text:"精诚",glossary:"yf4-jingcheng"},"之",{text:"至",glossary:"yf4-zhi"},"也。不精不诚，不能",{text:"动人",glossary:"yf4-dongren"},"。"]]},{id:"yufu-p4-02",label:"强作与真实",sentences:[["故",{text:"强哭",glossary:"yf4-qiangku"},"者，",{text:"虽悲不哀",glossary:"yf4-beibuai"},"，",{text:"强怒",glossary:"yf4-qiangnu"},"者，",{text:"虽严不屯",glossary:"yf4-yanbuzhun"},"，强",{text:"亲",glossary:"yf4-qin"},"者，虽笑不",{text:"和",glossary:"yf4-he"},"。"],["真悲无声而哀，真怒未发而威，真",{text:"亲",glossary:"yf4-qin"},"未笑而",{text:"和",glossary:"yf4-he"},"。"],["真在内者，",{text:"神动于外",glossary:"yf4-shendong"},"，是所以贵真也。"]]},{id:"yufu-p4-03",label:"真用于人理",sentences:[["其用于",{text:"人理",glossary:"yf4-renli"},"也，事亲则",{text:"慈孝",glossary:"yf4-cixiao"},"，事君则",{text:"忠贞",glossary:"yf4-zhongzhen"},"，饮酒则欢乐，处丧则悲哀。"],["忠贞以",{text:"功",glossary:"yf4-gong"},"为主，饮酒以乐为主，处丧以哀为主，事亲以",{text:"适",glossary:"yf4-shi"},"为主。"]]},{id:"yufu-p4-04",label:"内容与行迹",sentences:[["功成之美，",{text:"无一其迹",glossary:"yf4-wuyiqiji"},"矣；事亲以适，不论",{text:"所以",glossary:"yf4-suoyi"},"矣；饮酒以乐，不选其",{text:"具",glossary:"yf4-ju"},"矣；处丧以哀，",{text:"无问其礼",glossary:"yf4-wuwenqili"},"矣。"]]},{id:"yufu-p4-05",label:"法天贵真",sentences:[["礼者，世俗之所为也；真者，所以",{text:"受于天",glossary:"yf4-shouyutian"},"也，自然不可易也。"],["故圣人",{text:"法天",glossary:"yf4-fatian"},"贵真，不拘于俗。愚者反此。"],["不能法天而",{text:"恤于人",glossary:"yf4-xuyuren"},"，不知贵真，",{text:"禄禄",glossary:"yf4-lulu"},"而",{text:"受变于俗",glossary:"yf4-shoubian"},"，故不足。"],["惜哉，子之",{text:"蚤湛",glossary:"yf4-zaozhan"},"于",{text:"伪",glossary:"yf4-wei"},"而晚闻大道也！”"]]},{id:"yufu-p4-06",label:"请求受业",sentences:[["孔子再拜而起曰：“今者丘",{text:"得遇",glossary:"yf4-deyu"},"也，若",{text:"天幸",glossary:"yf4-tianxing"},"然。"],["先生不羞而",{text:"比之服役",glossary:"yf4-bizhifuyi"},"而",{text:"身教之",glossary:"yf4-shenjiao"},"。"],["敢问",{text:"舍",glossary:"yf4-she"},"所在，请因",{text:"受业",glossary:"yf4-shouye"},"而",{text:"卒学",glossary:"yf4-zuxue"},"大道。”"]]},{id:"yufu-p4-07",label:"同行条件",sentences:[["客曰：“吾闻之，",{text:"可与往",glossary:"yf4-keyuwang"},"者，与之至于",{text:"妙道",glossary:"yf4-miaodao"},"；",{text:"不可与往者，不知其道",glossary:"yf4-bukeyuwang"},"。"],["慎勿与之，身乃无",{text:"咎",glossary:"yf4-jiu"},"。"]]},{id:"yufu-p4-08",label:"自勉与辞别",sentences:[["子勉之，吾去子矣，吾去子矣！”"],["乃",{text:"剌船",glossary:"yf4-lachuan"},"而去，",{text:"延缘苇间",glossary:"yf4-yanyuan"},"。"]]},{id:"yufu-p5-01",label:"离去后的等待",sentences:[[{text:"颜渊",glossary:"yf5-yanyuan"},{text:"还车",glossary:"yf5-huanche"},"，子路",{text:"授绥",glossary:"yf5-shousui"},"，孔子",{text:"不顾",glossary:"yf5-bugu"},"，待水波定，不闻",{text:"拏音",glossary:"yf5-nayin"},"而后敢乘。"]]},{id:"yufu-p5-02",label:"子路比较",sentences:[["子路",{text:"旁车",glossary:"yf5-pangche"},"而问曰：“",{text:"由",glossary:"yf5-you"},"得",{text:"为役",glossary:"yf5-weiyi"},"久矣，未尝见夫子遇人",{text:"如此其威",glossary:"yf5-wei"},"也。"],[{text:"万乘",glossary:"yf5-wancheng"},"之主，",{text:"千乘",glossary:"yf5-qiancheng"},"之君，见夫子未尝不",{text:"分庭伉礼",glossary:"yf5-fenting"},"，夫子犹有",{text:"倨傲",glossary:"yf5-juao"},"之容。"]]},{id:"yufu-p5-03",label:"恭敬之问",sentences:[["今渔父",{text:"杖拏逆立",glossary:"yf5-zhangna"},"，而夫子",{text:"曲要",glossary:"yf5-quyao"},{text:"磬折",glossary:"yf5-qingzhe"},"，",{text:"言拜而应",glossary:"yf5-yanbai"},"，",{text:"得无太甚乎",glossary:"yf5-dewu"},"！"],["门人皆",{text:"怪",glossary:"yf5-guai"},"夫子矣，渔父何以得此乎！”"]]},{id:"yufu-p5-04",label:"久学与难化",sentences:[["孔子",{text:"伏轼",glossary:"yf5-fushi"},"而叹，曰：“甚矣，由之难",{text:"化",glossary:"yf5-hua"},"也！"],[{text:"湛于礼义",glossary:"yf5-zhanyu"},{text:"有间",glossary:"yf5-youjian"},"矣，而",{text:"朴鄙",glossary:"yf5-pubi"},"之心至今未去。"]]},{id:"yufu-p5-05",label:"敬长与尊贤",sentences:[["进，吾语汝：夫遇",{text:"长",glossary:"yf5-zhang"},"不敬，失礼也；见贤不尊，不仁也。"]]},{id:"yufu-p5-06",label:"精诚谦下",sentences:[["彼非",{text:"至人",glossary:"yf5-zhiren"},"，不能",{text:"下人",glossary:"yf5-xiaren"},"。下人",{text:"不精",glossary:"yf5-bujing"},"，不得其真，故",{text:"长伤身",glossary:"yf5-changshang"},"。"],["惜哉！不仁之于人也，祸莫大焉，而由独",{text:"擅之",glossary:"yf5-shanzhi"},"。"]]},{id:"yufu-p5-07",label:"道与生死成败",sentences:[["且道者，",{text:"万物之所由",glossary:"yf5-suoyou"},"也。",{text:"庶物",glossary:"yf5-shuwu"},"失之者死，得之者生。"],["为事逆之则败，顺之则成。"]]},{id:"yufu-p5-08",label:"尊道作答",sentences:[["故道之所在，圣人尊之。"],["今之渔父之",{text:"于道，可谓有矣",glossary:"yf5-youyudao"},"，吾敢不敬乎！”"]]},{id:"yufu-p2-01",label:"同类相从·四类分职",sentences:[["同类相从，同声相应，固",{text:"天之理",glossary:"yf2-tianzhili"},"也。吾请",{text:"释吾所有",glossary:"yf2-shisuo"},"而",{text:"经子之所以",glossary:"yf2-jingzi"},"。子之所以者，人事也。"]]},{id:"yufu-p2-02",label:"四者自正·乃无所陵",sentences:[["天子诸侯大夫庶人，此",{text:"四者自正",glossary:"yf2-sizhe"},"，治之美也；四者",{text:"离位",glossary:"yf2-liwei"},"而乱莫大焉。官治其职，人忧其事，乃",{text:"无所陵",glossary:"yf2-wusuoling"},"。"]]},{id:"yufu-p2-03",label:"庶人之忧",sentences:[["故",{text:"田荒室露",glossary:"yf2-tianhuang"},"，衣食不足，",{text:"征赋不属",glossary:"yf2-zhengfu"},"，妻妾不和，",{text:"长少无序",glossary:"yf2-changshao"},"，庶人之忧也。"]]},{id:"yufu-p2-04",label:"大夫之忧",sentences:[[{text:"能不胜任",glossary:"yf2-bushengren"},"，官事不治，",{text:"行不清白",glossary:"yf2-qingbai"},"，群下荒怠，功美不有，",{text:"爵禄不持",glossary:"yf2-juelu"},"，大夫之忧也。"]]},{id:"yufu-p2-05",label:"诸侯之忧",sentences:[["廷无忠臣，国家昏乱，工技不巧，贡职不美，",{text:"春秋后伦",glossary:"yf2-houlun"},"，不顺天子，诸侯之忧也。"]]},{id:"yufu-p2-06",label:"天子有司之忧",sentences:[[{text:"阴阳不和",glossary:"yf2-yinyang"},"，寒暑不时，以伤庶物；诸侯暴乱，擅相攘伐，以残民人；礼乐不节，",{text:"财用穷匮",glossary:"yf2-caiyong"},"，",{text:"人伦不饬",glossary:"yf2-renlun"},"，百姓淫乱，天子有司之忧也。"]]},{id:"yufu-p2-07",label:"无位而越位之问",sentences:[["今子既上无君侯有司之势，而下无大臣职事之官，而",{text:"擅饰礼乐",glossary:"yf2-shanshi"},"，",{text:"选人伦",glossary:"yf2-xuanrenlun"},"，以",{text:"化齐民",glossary:"yf2-huaqimin"},"，",{text:"不泰多事",glossary:"yf2-taiduos"},"乎！"]]},{id:"yufu-p2-08",label:"八疵之名",sentences:[["且人有",{text:"八疵",glossary:"yf2-baci"},"，事有",{text:"四患",glossary:"yf2-sihuan"},"，不可不察也。非其事而事之，谓之",{text:"摠",glossary:"yf2-zong"},"；莫之顾而进之，谓之",{text:"佞",glossary:"yf2-ning"},"；希意道言，谓之",{text:"谄",glossary:"yf2-chan"},"；不择是非而言，谓之",{text:"谀",glossary:"yf2-yu"},"；好言人之恶，谓之",{text:"谗",glossary:"yf2-chan2"},"；析交离亲，谓之",{text:"贼",glossary:"yf2-zei"},"；称誉诈伪以败恶人，谓之",{text:"慝",glossary:"yf2-te"},"；不择善否，两容颊适，偷拔其所欲，谓之",{text:"险",glossary:"yf2-xian"},"。"]]},{id:"yufu-p2-09",label:"八疵之害",sentences:[["此八疵者，外以乱人，内以伤身，君子不友，明君不臣。"]]},{id:"yufu-p2-10",label:"四患之名",sentences:[["所谓四患者：好经大事，变更易常，以挂功名，谓之",{text:"叨",glossary:"yf2-tao"},"；专知擅事，侵人自用，谓之",{text:"贪",glossary:"yf2-tan"},"；见过不更，闻谏愈甚，谓之",{text:"很",glossary:"yf2-hen"},"；人同于己则可，不同于己，虽善不善，谓之",{text:"矜",glossary:"yf2-jin"},"。"]]},{id:"yufu-p2-11",label:"去八疵而后可教",sentences:[["此四患也。能去八疵，无行四患，而",{text:"始可教",glossary:"yf2-shikejiao"},"已。"]]}],f=[{text:"同类相从，同声相应，固天之理也。",guide:"渔父先立自然条理，再说自己要讲什么——进言有据，不是凭长者身份压人。"},{text:"此四者自正，治之美也；四者离位而乱莫大焉。",guide:"治乱的关键在「各安其位」，而不在职位本身高低。",note:"不等于越出本位就一定正确，仍要看越出之后做了什么。"},{text:"今子既上无君侯有司之势，而下无大臣职事之官，而擅饰礼乐，选人伦，以化齐民，不泰多事乎！",guide:"批评落点很清楚：不是不该关心天下，而是无其位而行其事。",note:"此句是反问，不构成对一切公共参与的禁令。"},{text:"非其事而事之，谓之摠……不择善否，两容颊适，偷拔其所欲，谓之险。",guide:"八疵都在「怎样待人接物」上，逐条都是可指认的行为，不是给人贴品格标签。",note:"不必把日常的善意寒暄一律判为谄谀。"},{text:"所谓四患者：好经大事……虽善不善，谓之矜。",guide:"四患都在「怎样任事」上：揽大、专断、拒谏、自矜。",note:"与八疵分列，一在待人，一在任事，不宜混为一单。"},{text:"能去八疵，无行四患，而始可教已。",guide:"渔父把「可教」设成条件：先去掉这些毛病，才谈得上受教。",note:"这不是拒绝教人，而是指出受教也需要前提。"}],m=[{text:"吾请释吾所有而经子之所以。",guide:"渔父明说自己要做什么：把所懂的讲清，再条理对方所做。",note:"他说的是「所以」，不是「其人」——评论对象是行为，不是人格。"},{text:"天子诸侯大夫庶人，此四者自正，治之美也。",guide:"先承认四类职分各有其正当性，治的前提是各安其位。",note:"不由此推出等级本身不可讨论。"},{text:"故田荒室露，衣食不足……长少无序，庶人之忧也。",guide:"四类之忧都写得极具体：田、衣、赋、家、位、禄、伦、财。",note:"具体到这一层，议论才不是空话。"},{text:"今子既上无君侯有司之势……不泰多事乎！",guide:"由四类之忧转到孔子身上：无位而治，正是此处被质疑的地方。",note:"可与《论语》「不在其位，不谋其政」对读，但两处语境不同。"},{text:"且人有八疵，事有四患，不可不察也。",guide:"八疵、四患是渔父给的两张清单：一张待人，一张任事。",note:"清单可用来检省自己，不宜拿去给别人点名。"},{text:"能去八疵，无行四患，而始可教已。",guide:"全段的落点：受教有条件。孔子随后正是接住了这个条件。",note:"不据此把「不可教」当成拒绝他人的理由。"}],x=[{text:"孔氏者何治也？",guide:"所治：从人物名声转向实际所行：孔子究竟致力于什么？子贡以忠信、仁义、礼乐、人伦与利天下作答。",note:"这是弟子对老师的称述，不直接等于叙述者对其全部实践的裁定。"},{text:"有土之君与？……侯王之佐与？",guide:"所事与所位：渔父在了解孔子的公共目标后，进一步询问他是否处于相应的政治位置，为后文职分论作准备。",note:"本份尚未完成论证，不能提前归结为无官位者都不应关心天下。"},{text:"仁则仁矣，恐不免其身。",guide:"仁与代价：先承认仁心，再检验行动的方式与代价。善意并不自动保证行动合宜。",note:"不宜将这句话解释成彻底否认仁义，或认定一切公共实践必然伤身。"},{text:"苦心劳形以危其真。",guide:"危真与远道：批评超出一般的劳累提醒，指向外在经营是否损害自身之真、使人与道相离。",note:"“真”此处仍是待解释的关键词，不预先固定为任性、退避或完全不行动。"},{text:"无所得闻至教，敢不虚心！",guide:"虚心与求教：孔子不以年龄、学习经历与既有名声作为拒绝新教诲的依据。",note:"虚心说明愿意听，不等于已经理解或接受渔父的全部结论。"}],q=[{text:"丘不知所失，而离此四谤者何也？",guide:"所失与困厄：孔子由自身遭遇追问行动的失当之处，试图重新理解困厄。",note:"追问自身，不等于已经确认所有困厄都是自己的过错。"},{text:"举足愈数而迹愈多，走愈疾而影不离身。",guide:"办法与目标：奔跑既增加脚印，也不能摆脱影子；办法与所求目标发生冲突。",note:"譬喻批评的是失当办法，不是所有努力。"},{text:"自以为尚迟。",guide:"错误诊断：把办法没有奏效误认成用力不足，于是更强地重复原办法。",note:"不宜反向断定每一次失败都意味着办法错误，仍须检验具体情境。"},{text:"处阴以休影，处静以息迹。",guide:"改变条件：不再与影子竞速，而是改变环境、停止制造新的脚印。",note:"处静是针对譬喻中问题的办法，不是一切处境的统一答案。"},{text:"谨修而身，慎守其真。",guide:"修身守真：将着力点从广泛经营外在关系转回自身的根据。",note:"守真不等于任性、拒绝关系或取消一切责任。"},{text:"今不修之身而求之人，不亦外乎！",guide:"向外与包揽：检省持续向外求取、尽揽事务的方式，不把解决问题的根据全放在他人身上。",note:"自我检省不能替代对外部伤害及其责任的辨明。"}],c=[{text:"真者，精诚之至也。",guide:"精诚之至：真涉及情感与行动的精诚根据，不限于言语是否符合事实。",note:"能感动别人不必然证明真实，不能将感发效果作为唯一测试。"},{text:"真悲无声而哀，真怒未发而威，真亲未笑而和。",guide:"强作与真情：真实内容不以完成哭、怒、笑等动作作为必要凭证。",note:"并非要求不哭、不怒、不笑，也不是情感真实便可任意表达。"},{text:"真在内者，神动于外。",guide:"内外相应：真实会感发于外，关键是外在表现有没有内在精诚作为根据。",note:"不能简单分成内在都真、外在都假。"},{text:"忠贞以功为主，饮酒以乐为主，处丧以哀为主，事亲以适为主。",guide:"功、乐、哀、适：真用于人事，不只在表态，还要实现事务所应有的具体内容。",note:"不拘固定形式不等于任何方式都合宜。"},{text:"故圣人法天贵真，不拘于俗。",guide:"法天贵真：不让俗习与他人评价压过真实内容；此处对礼俗的批评具有鲜明力度。",note:"既不能淡化为一般的形式灵活，也不能直接推出废除一切礼仪。"},{text:"子勉之，吾去子矣，吾去子矣！",guide:"受业与辞别：孔子请求继续学习，渔父却未承诺长期授业，相遇在鼓励自勉中结束。",note:"没有明确判定孔子完全不可教，也没有保证日后继续相从。"}],k=[{text:"渔父何以得此乎！",guide:"恭敬的根据：子路比较老师面对君主与渔父的不同姿态，追问尊敬的根据与程度。",note:"不能将子路的疑问简单归为无端挑衅，或只读成对低身份者的轻视。"},{text:"湛于礼义有间矣，而朴鄙之心至今未去。",guide:"久学与难化：熟悉礼义、长期随侍，不等于看待他人的尺度已经改变。",note:"不意味着子路过去所有学习都无价值，也不是否定提问本身。"},{text:"夫遇长不敬，失礼也；见贤不尊，不仁也。",guide:"敬长与尊贤：孔子以长者、贤者说明敬人的根据，不以政治权势作为唯一尺度。",note:"篇末仍使用礼仁语言，与前文批评礼俗之间的张力不能完全抹平。"},{text:"下人不精，不得其真。",guide:"精诚谦下：谦下的动作也须有精诚作为根据，礼貌不能自动证明真实敬重。",note:"“下人”是谦下于人，不是指所谓下等人。"},{text:"故道之所在，圣人尊之。",guide:"尊道超出显位：孔子认为渔父于道有所得，因此值得郑重尊敬与求教。",note:"尊敬的根据与事务的权限不同，不能由尊道取消一切职分边界。"},{text:"吾敢不敬乎！",guide:"转变的限度：故事写出孔子对这次相遇的解释，以及对敬人、受教的说明。",note:"没有展开长期践行的结果，不能据此确认孔子已经全面得道。"}],P=[{text:"弟子读书，孔子弦歌鼓琴。",guide:"先呈现师生共处、读书与音乐的生活场景，尚未直接判定这种生活有罪。",note:"渔父的批评是在听曲之前就成立，还是经过询问才形成？"},{text:"将以利天下。",guide:"子贡突出孔子的公共目标；后文需要检验的是目标怎样实行，而不只看目标是否善。",note:"所愿良善，是否足以保证方式合宜、后果无害？"},{text:"仁则仁矣，恐不免其身。",guide:"承认与保留同时出现，是理解初次批评的关键。",note:"渔父是在否认仁心，还是在追问仁心实现时的代价？"},{text:"孔子推琴而起。",guide:"虚心首先表现为行动：放下原先的活动，主动寻找批评者。",note:"孔子为什么没有先维护名声或反驳来者？"},{text:"未知所谓。",guide:"孔子明说尚未理解，请求把初次批评展开。",note:"恭敬求教与已经接受结论，为什么需要分开？"},{text:"敢不虚心！",guide:"长期修学并未被用作免于受教的资格，反而成为继续学习的背景。",note:"已有经验如何帮助学习，又可能怎样阻挡新的理解？"}],z=[{text:"丘不知所失。",guide:"孔子的切身追问将教诲从一般清单转向自身经历。",note:"寻求自身所失，为什么不等于承担全部外部责任？"},{text:"甚矣，子之难悟也！",guide:"愿意听、恭敬听与真正领悟之间仍有距离。",note:"谦敬的表态之后，还需要发生什么改变？"},{text:"自以为尚迟。",guide:"关键转折在错误诊断：不是检验奔跑能否奏效，而是继续要求自己加速。",note:"问题没有减少时，是否总应先增加投入？"},{text:"处阴以休影，处静以息迹。",guide:"改变条件与停止追加，区别于加倍重复原办法。",note:"影子不再显现与不再产生脚印，分别依赖什么条件？"},{text:"而几于不免矣。",guide:"细密经营并未自动保全自身，认真程度不能代替整体方向的检验。",note:"为什么周密不必然等于合宜？"},{text:"谨修而身，慎守其真。",guide:"原文仍然要求修治，只是将修治的根据转回自身。",note:"本份已经说明“真”的方向，还是已经完整定义了“真”？"}],T=[{text:"请问何谓真？",guide:"孔子将教诲中的关键词提出来追问，不把守真当作已经理解的口号。",note:"接受一个方向与理解其内容，有什么区别？"},{text:"不精不诚，不能动人。",guide:"渔父以感发说明精诚的力量，但不应反向将动人效果等同于真实。",note:"为什么令人感动的表现仍可能需要检验？"},{text:"真在内者，神动于外。",guide:"内在与外在相互关联，外在动作并非必然虚假。",note:"同样的哭、笑或礼貌动作，为什么可能有不同根据？"},{text:"其用于人理也。",guide:"真仍须在事亲、事君、交往与丧事中实行。",note:"修身守真为什么不能简单理解为退出一切关系？"},{text:"功成之美，无一其迹矣。",guide:"事务内容可以通过不同方式实现，不把单一行迹作为唯一标准。",note:"形式是否合宜，应回到哪些具体内容检验？"},{text:"法天贵真，不拘于俗。",guide:"礼俗不能因被普遍遵循，就自动压过真实内容。",note:"这里对礼俗的批评，与篇末孔子的礼仁表达怎样相接？"},{text:"可与往者，与之至于妙道。",guide:"共同进于道需要条件，求学请求不自动建立长期授业关系。",note:"渔父实际承诺了什么，又没有承诺什么？"}],_=[{text:"待水波定，不闻拏音而后敢乘。",guide:"渔父离去后，孔子的敬意仍以等待的行动延续。",note:"这一动作如何呈现敬意，又为何不能独自证明全部内心状态？"},{text:"得无太甚乎！",guide:"子路不仅问渔父凭什么受敬，也问恭敬为何如此深切。",note:"尊敬的根据与表达的程度，是否需要分别解释？"},{text:"甚矣，由之难化也！",guide:"照应渔父对孔子的“难悟”之叹，继续追问学习有没有改变原有判断。",note:"学习很久与能够改变，为什么不是同一件事？"},{text:"遇长不敬，失礼也；见贤不尊，不仁也。",guide:"孔子仍以礼仁解释恭敬，但敬人的根据不只在权位。",note:"这里的礼仁表达与“不拘于俗”有哪些相接之处，又有哪些差异？"},{text:"下人不精，不得其真。",guide:"弯腰、再拜等形式仍须回到精诚检验。",note:"表现得谦逊与真正承认他人的所得，有什么区别？"},{text:"道之所在，圣人尊之。",guide:"篇末以渔父于道有所得回答受敬之问。",note:"为什么做事的职分与值得听学的对象不能混为一谈？"}],w={p1:"yufu-p1",p2:"yufu-p2",p3:"yufu-p3",p4:"yufu-p4",p5:"yufu-p5"};function p(u){return b.filter(t=>t.id.startsWith(w[u]))}function y(u){const t=new Set;for(const i of p(u))for(const s of i.sentences)for(const o of s)typeof o!="string"&&o.glossary&&t.add(o.glossary);return h.filter(i=>t.has(i.id)&&Array.from(i.term).length<=5)}const j=p("p1"),S=y("p1"),A=p("p2"),C=y("p2"),V=p("p3"),I=y("p3"),R=p("p4"),D=y("p4"),N=p("p5"),E=y("p5");return(u,t)=>{const i=g("DaoReadingPrelude"),s=g("DaoTextReading"),o=g("DaoKeywordCards"),r=g("DaoLineGuide");return v(),B("div",null,[t[0]||(t[0]=e("h1",{id:"庄子·渔父",tabindex:"-1"},[d("庄子·渔父 "),e("a",{class:"header-anchor",href:"#庄子·渔父","aria-label":'Permalink to "庄子·渔父"'},"​")],-1)),a(i,{title:"从被评论到主动求教",summary:"先看双方怎样相遇、渔父依据什么提出批评，以及孔子怎样回应。阅读时区分原文叙事、人物判断与引申解读。"}),t[1]||(t[1]=n('<p>《渔父》的故事由一次林中相遇展开。渔父先听琴歌，再向弟子询问孔子的身份、所治与政治位置；孔子听到批评后，主动追寻，请求解释未尽之言。</p><p>本篇后续将依次涉及：</p><ol><li>四类职分与各自所忧。</li><li>八疵、四患与受教的条件。</li><li>畏影恶迹与修身守真。</li><li>精诚、礼俗及真在人事中的应用。</li><li>子路质疑与孔子对尊贤、尊道的说明。</li></ol><p>**这里先列出阅读路线，不提前将全篇归结为单一结论。**尤其不能仅凭开篇批评，就认定仁义、读书、音乐或公共参与都已被否定。</p><h2 id="一、林中相遇·身份询问·初次批评·孔子追寻求教" tabindex="-1">一、林中相遇·身份询问·初次批评·孔子追寻求教 <a class="header-anchor" href="#一、林中相遇·身份询问·初次批评·孔子追寻求教" aria-label="Permalink to &quot;一、林中相遇·身份询问·初次批评·孔子追寻求教&quot;">​</a></h2><h3 id="本份范围" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“孔子游乎缁帷之林……”</li><li><strong>止于</strong>：“无所得闻至教，敢不虚心！”</li><li><strong>本份重点</strong>：相遇方式、批评依据与求教姿态。</li><li><strong>尚未展开</strong>：「真」的完整说明（四类职分与八疵四患见第二节）。</li></ul><blockquote><p>本份完成的不是道理的证明，而是受教关系的开启。</p></blockquote><h3 id="原文·连续阅读" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',9)),a(s,{sections:l(j),glossary:h,"default-mode":"classic","aria-label":"渔父·第1份 原文"},null,8,["sections"]),t[2]||(t[2]=e("p",null,[e("strong",null,"文字说明")],-1)),t[3]||(t[3]=e("p",null,"原文依据所提供文本整理，仅调整排版与标点，不擅改文字。“行原以上”“距陆”“反走”等动作语词存在训释差异，词条只说明基本语意，不强定全部空间位置与动作细节。",-1)),t[4]||(t[4]=e("p",null,"本篇先作为具有完整叙事与思想结构的故事阅读，不直接据此确认孔子晚年的真实行踪或交往记录。",-1)),t[5]||(t[5]=e("h3",{id:"关键词卡片",tabindex:"-1"},[d("关键词卡片 "),e("a",{class:"header-anchor",href:"#关键词卡片","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:l(S)},null,8,["items"]),t[6]||(t[6]=e("h3",{id:"核心句引读",tabindex:"-1"},[d("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:x}),t[7]||(t[7]=e("h3",{id:"逐句导读",tabindex:"-1"},[d("逐句导读 "),e("a",{class:"header-anchor",href:"#逐句导读","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:P}),t[8]||(t[8]=n('<h3 id="一、开篇的孔子-正在实践弟子所称述的生活" tabindex="-1">一、开篇的孔子：正在实践弟子所称述的生活 <a class="header-anchor" href="#一、开篇的孔子-正在实践弟子所称述的生活" aria-label="Permalink to &quot;一、开篇的孔子：正在实践弟子所称述的生活&quot;">​</a></h3><blockquote><p>弟子读书，孔子弦歌鼓琴。</p></blockquote><p>故事没有先写争论，而是写读书、音乐与师生共处。子贡后面所说的礼乐与教化，在开篇已有相应场景。</p><p>孔子不是只在口头宣讲，他正在带着弟子生活、学习。但不能由此直接判定：</p><ul><li>此刻的弦歌就是虚伪。</li><li>渔父反对所有音乐。</li><li>读书本身就是危真之事。</li></ul><p>渔父最初的批评，还需要经过询问才能形成。<strong>开篇呈现一种生活方式，尚未直接给它定罪。</strong></p><h3 id="二、渔父先听完-再招弟子问话" tabindex="-1">二、渔父先听完，再招弟子问话 <a class="header-anchor" href="#二、渔父先听完-再招弟子问话" aria-label="Permalink to &quot;二、渔父先听完，再招弟子问话&quot;">​</a></h3><p>渔父下船而来，按膝托颐，听到曲终。这组动作既写出年长来者的形貌，也使他先作为倾听者进入故事。</p><p>他没有在曲中打断孔子，也没有一到场就宣布大道。故事先让他听，再让他问。</p><p>不过，倾听琴歌不等于已经了解孔子的全部思想与经历。后面的判断，主要依据弟子对孔子所治之事的说明。</p><p><strong>读者应当保留判断所依据的信息范围。</strong></p><h3 id="三、三层询问-是谁、做什么、居什么位置" tabindex="-1">三、三层询问：是谁、做什么、居什么位置 <a class="header-anchor" href="#三、三层询问-是谁、做什么、居什么位置" aria-label="Permalink to &quot;三、三层询问：是谁、做什么、居什么位置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>问题</th><th>回答</th></tr></thead><tbody><tr><td>人物身份</td><td>“彼何为者也？”“其族”</td><td>鲁之君子，孔氏</td></tr><tr><td>实践内容</td><td>“孔氏者何治也？”</td><td>忠信、仁义、礼乐、人伦、利天下</td></tr><tr><td>政治位置</td><td>“有土之君与？”“侯王之佐与？”</td><td>都不是</td></tr></tbody></table><p>“鲁之君子”是一种尊称与人物评价，却没有回答其具体事务，因此渔父继续问“何治”。</p><p>得知其所治之后，又问有无君主、辅臣的位置。询问的重点，由名声转向实践，再转向实践与位置是否相称。</p><p>这一顺序，为下一份的职分论作了准备，但本份尚未给出完整论证。</p><h3 id="四、子贡的介绍-善意、实践与天下目标" tabindex="-1">四、子贡的介绍：善意、实践与天下目标 <a class="header-anchor" href="#四、子贡的介绍-善意、实践与天下目标" aria-label="Permalink to &quot;四、子贡的介绍：善意、实践与天下目标&quot;">​</a></h3><p>子贡的回答有三个层次。</p><p><strong>第一层：内在所服膺。</strong></p><blockquote><p>性服忠信。</p></blockquote><p>说明孔子以忠信为准则。</p><p><strong>第二层：身体力行与秩序经营。</strong></p><blockquote><p>身行仁义，饰礼乐，选人伦。</p></blockquote><p>既包括自身实践，也包括礼乐、人伦的修治。“饰”不宜直接解释成虚假装饰，“选”也不只指挑选人员。</p><p><strong>第三层：对外目标。</strong></p><blockquote><p>上以忠于世主，下以化于齐民，将以利天下。</p></blockquote><p>孔子的目标不是只求个人安顿，而是面向君主、民众与天下。</p><p>在子贡的介绍中，内在品格、外在实践与公共目标彼此贯通。但这仍是弟子对老师的称述。</p><p>后面渔父所追问的，正是：<strong>有这样的品格与目标，是否就足以保证行动合宜、后果无害？</strong></p><h3 id="五、两次-非也-让所事与所位之间的差异显出来" tabindex="-1">五、两次“非也”：让所事与所位之间的差异显出来 <a class="header-anchor" href="#五、两次-非也-让所事与所位之间的差异显出来" aria-label="Permalink to &quot;五、两次“非也”：让所事与所位之间的差异显出来&quot;">​</a></h3><p>渔父问孔子是否为有土之君，又问是否为侯王之佐，子贡两次否定。</p><p>由此形成一个需要解释的关系：</p><blockquote><p>孔子承担广泛的教化目标，却没有渔父所询问的相应政治位置。</p></blockquote><p>本份中，渔父还没有把这个关系充分论证。因此，不宜提前归结成：</p><blockquote><p>没有官位，就不应该关心天下。</p></blockquote><p>下一份将说明他的职分观念，并具体指向孔子的做法。这里先提出问题，不替后文抢作普遍结论。</p><h3 id="六、-仁则仁矣-承认仁心-却不以仁心结束判断" tabindex="-1">六、“仁则仁矣”：承认仁心，却不以仁心结束判断 <a class="header-anchor" href="#六、-仁则仁矣-承认仁心-却不以仁心结束判断" aria-label="Permalink to &quot;六、“仁则仁矣”：承认仁心，却不以仁心结束判断&quot;">​</a></h3><blockquote><p>仁则仁矣，恐不免其身。</p></blockquote><p>这句话不是彻底否认孔子的仁。它的结构是：<strong>承认其仁，再提出保留。</strong></p><p>因而，渔父的批评不能简单说成“仁义都是假的”。更准确的是：</p><blockquote><p>即使确有仁心，仍须检验其行动是否伤身、危真、远道。</p></blockquote><p>子贡强调利天下，渔父则把注意力转到孔子自身承受的代价。</p><table tabindex="0"><thead><tr><th>子贡着重</th><th>渔父着重</th></tr></thead><tbody><tr><td>所服膺的准则</td><td>行动是否合宜</td></tr><tr><td>所实行的仁义</td><td>是否苦心劳形</td></tr><tr><td>利天下的目标</td><td>是否危真、难免其身</td></tr></tbody></table><p><strong>善意不自动证明方式正确，也不自动免除代价问题。</strong></p><h3 id="七、-危其真-与-分于道-先提出核心问题-尚未解释到底" tabindex="-1">七、“危其真”与“分于道”：先提出核心问题，尚未解释到底 <a class="header-anchor" href="#七、-危其真-与-分于道-先提出核心问题-尚未解释到底" aria-label="Permalink to &quot;七、“危其真”与“分于道”：先提出核心问题，尚未解释到底&quot;">​</a></h3><blockquote><p>苦心劳形以危其真。<br> 远哉，其分于道也。</p></blockquote><p>这使批评超出一般的劳累提醒。他担心的不只是“孔子忙得太累”，而是这样的经营方式可能损害自身之真，并使其与道相离。</p><p>但“真”在这里还没有定义。后面孔子会直接问“何谓真”，渔父才以精诚及其在人事中的表现展开说明。</p><p>因而，本份不宜把真固定解释成：</p><ul><li>任性随意。</li><li>完全不行动。</li><li>只顾自己。</li><li>一种不受任何关系影响的情绪。</li></ul><p><strong>“危真”是本篇的伏笔，也是后续问答需要解决的问题。</strong></p><h3 id="八、推琴而起-孔子把批评当成求教的线索" tabindex="-1">八、推琴而起：孔子把批评当成求教的线索 <a class="header-anchor" href="#八、推琴而起-孔子把批评当成求教的线索" aria-label="Permalink to &quot;八、推琴而起：孔子把批评当成求教的线索&quot;">​</a></h3><p>子贡回报后，孔子问：</p><blockquote><p>其圣人与？</p></blockquote><p>随即推琴起身，追至泽畔。这一反应与维护名声、反驳来者不同。</p><p>他没有先要求弟子证明自己，也没有因对方是渔父而忽略其言。</p><p>“其圣人与”仍是推测，不是叙述者已经证明渔父为圣人。但它足以说明：孔子从批评中听出了值得追问的可能。</p><p><strong>这里的虚心先表现为行动：放下正在进行的活动，主动寻找说话者。</strong></p><h3 id="九、水边相见-一个准备离去-一个主动追来" tabindex="-1">九、水边相见：一个准备离去，一个主动追来 <a class="header-anchor" href="#九、水边相见-一个准备离去-一个主动追来" aria-label="Permalink to &quot;九、水边相见：一个准备离去，一个主动追来&quot;">​</a></h3><p>孔子到泽畔时，渔父正准备引船离岸。看见孔子，渔父转身站定。</p><p>双方的行动形成对照：</p><ul><li>渔父并未留在原处等待收徒。</li><li>孔子主动追来，希望听到未尽之言。</li></ul><p>这场教诲不是由渔父预先建立的师徒关系开始，而是由孔子的追问延续。</p><p>这一安排也照应后文：孔子最终希望继续受业，渔父却仍选择离去。</p><p><strong>渔父愿意说话，不等于愿意建立长期授业关系。</strong></p><h3 id="十、绪言与下风-孔子请求把初次批评展开" tabindex="-1">十、绪言与下风：孔子请求把初次批评展开 <a class="header-anchor" href="#十、绪言与下风-孔子请求把初次批评展开" aria-label="Permalink to &quot;十、绪言与下风：孔子请求把初次批评展开&quot;">​</a></h3><blockquote><p>曩者先生有绪言而去……丘不肖，未知所谓……</p></blockquote><p>孔子把渔父先前的话当作尚待展开的开端。请求的核心是：</p><blockquote><p>我还不知道你的意思，希望得到进一步帮助。</p></blockquote><p>“不肖”“下风”“咳唾之音”等，是郑重而谦敬的表达，不宜按字面读成：</p><ul><li>孔子只想听对方咳嗽。</li><li>对方的教诲毫无价值。</li><li>孔子已经理解并接受全部批评。</li></ul><p>谦辞建立求教姿态，而“未知所谓”保留了尚未理解的事实。</p><h3 id="十一、六十九岁与-敢不虚心-学习经历不是免于受教的资格" tabindex="-1">十一、六十九岁与“敢不虚心”：学习经历不是免于受教的资格 <a class="header-anchor" href="#十一、六十九岁与-敢不虚心-学习经历不是免于受教的资格" aria-label="Permalink to &quot;十一、六十九岁与“敢不虚心”：学习经历不是免于受教的资格&quot;">​</a></h3><p>孔子说自己从少年修学，直到六十九岁。</p><p>按通常的自我辩护方式，长期学习可以被用来证明“我已有足够资格，不必再听别人”。但孔子在这里把它转成另一种表达：</p><blockquote><p>无所得闻至教，敢不虚心！</p></blockquote><p>学习很久，不等于已经穷尽可以学习的内容。这也不必按字面理解成孔子过去毫无所得。</p><p>更稳妥的是：<strong>在这场求教中，他不把年龄与既有成就作为拒绝新教诲的依据。</strong></p><p>渔父称其好学，孔子进一步表明虚心。到本份末尾，继续问答的条件已经形成。</p><h3 id="十二、与《盗跖》《说剑》的初步对读" tabindex="-1">十二、与《盗跖》《说剑》的初步对读 <a class="header-anchor" href="#十二、与《盗跖》《说剑》的初步对读" aria-label="Permalink to &quot;十二、与《盗跖》《说剑》的初步对读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>比较项</th><th>《盗跖》第一场</th><th>《说剑》</th><th>《渔父》本份</th></tr></thead><tbody><tr><td>相遇方向</td><td>孔子主动往说盗跖</td><td>庄子受托往说赵王</td><td>渔父先评论，孔子主动追问</td></tr><tr><td>开始的目标</td><td>使盗跖改行</td><td>使赵王停止喜剑</td><td>求明渔父未尽之言</td></tr><tr><td>对话条件</td><td>威胁、辱斥、价值冲突</td><td>剑士身份与共同兴趣</td><td>倾听、追寻与谦敬求教</td></tr><tr><td>孔子的位置</td><td>劝说者</td><td>非故事主角</td><td>求教者</td></tr></tbody></table><p>《渔父》中的孔子，并非从一开始就以教化者身份面对来者。他先是被评论的人，随后成为主动求教的人。</p><p>与《盗跖》相比，应当看见这种角色变化，而不只归成“孔子再次受批评”。</p><p>与《说剑》相比，两篇都检验所事与位置的关系。但《渔父》本份只提出了这个问题，尚未给出完整说明。</p><h3 id="本份·核心对照" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>林中场景</td><td>弟子读书，孔子弦歌鼓琴</td><td>学习与实践生活</td><td>读书、音乐本身已被否定</td></tr><tr><td>渔父来听</td><td>持颐以听，曲终而招</td><td>先倾听，再询问</td><td>已了解孔子的全部经历</td></tr><tr><td>实践介绍</td><td>将以利天下</td><td>弟子称述的公共目标</td><td>善意自动保证方式正确</td></tr><tr><td>位置追问</td><td>有土之君？侯王之佐？</td><td>所事与所位的关系</td><td>无官位者都不应关心天下</td></tr><tr><td>初次批评</td><td>仁则仁矣</td><td>承认仁心，同时提出保留</td><td>彻底否认一切仁义</td></tr><tr><td>代价问题</td><td>苦心劳形以危其真</td><td>劳形、危真与远道</td><td>真只是任性或不行动</td></tr><tr><td>孔子追寻</td><td>推琴而起，乃下求之</td><td>把批评转成求教线索</td><td>渔父的圣人身份已被证实</td></tr><tr><td>请求展开</td><td>有绪言而去，未知所谓</td><td>希望进一步理解</td><td>已经接受全部结论</td></tr><tr><td>虚心表态</td><td>敢不虚心</td><td>不以年龄与旧学拒绝受教</td><td>孔子过去完全没有所得</td></tr></tbody></table><h3 id="本份收束" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>第一节完成的不是道理的证明，而是受教关系的开启。</p><p>子贡以忠信、仁义与利天下说明孔子。渔父则提出：</p><blockquote><p>所愿虽善，是否仍可能因所事不当而苦心劳形、危及其真？</p></blockquote><p>孔子没有立即反驳，而是追问：</p><blockquote><p>这番话究竟意味着什么？</p></blockquote><p>到“敢不虚心”，双方已经具备继续问答的条件。下一份即渔父把初次批评展开：先列四类职分与四类之忧，再以八疵、四患界定什么叫「可教」。</p><h2 id="二、四类职分·八疵四患·受教的前提" tabindex="-1">二、四类职分·八疵四患·受教的前提 <a class="header-anchor" href="#二、四类职分·八疵四患·受教的前提" aria-label="Permalink to &quot;二、四类职分·八疵四患·受教的前提&quot;">​</a></h2>',94)),a(i,{title:"从「敢不虚心」到四类职分，再落到八疵四患",summary:"渔父接下孔子的虚心，先把天子、诸侯、大夫、庶人四类之憂逐一说明，指出「离位则乱」；再以八疵、四患两张清单界定什么叫可教，最后才谈得上后面那些话。"}),t[9]||(t[9]=n('<h3 id="本份范围-1" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-1" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：「同类相从，同声相应，固天之理也。」</li><li><strong>止于</strong>：「能去八疵，无行四患，而始可教已。」</li><li><strong>连续脉络</strong>：立自然条理 → 四类分职 → 四类之忧 → 无位而越位之问 → 八疵之名 → 八疵之害 → 四患之名 → 「而后可教」。</li></ul><p>第一节停在孔子「敢不虚心」。受教的前提已经立起，接着要看的便是：渔父究竟要教什么，又凭什么说孔子「多事」。</p><h3 id="原文·连续阅读-1" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-1" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',4)),a(s,{sections:l(A),glossary:h,"default-mode":"classic","aria-label":"渔父·第二节 原文"},null,8,["sections"]),t[10]||(t[10]=e("blockquote",null,[e("p",null,"**文字说明：**本份依所提供文本整理，标点略作调整。「摠」「佞」「慝」「很」等字的使用与训释各本有异；「选人伦」之「选」取简择、条理义，不作「挑选人才」解。")],-1)),t[11]||(t[11]=e("h3",{id:"关键词卡片-1",tabindex:"-1"},[d("关键词卡片 "),e("a",{class:"header-anchor",href:"#关键词卡片-1","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:l(C)},null,8,["items"]),t[12]||(t[12]=e("h3",{id:"核心句引读-1",tabindex:"-1"},[d("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:f}),t[13]||(t[13]=e("h3",{id:"逐句导读-1",tabindex:"-1"},[d("逐句导读 "),e("a",{class:"header-anchor",href:"#逐句导读-1","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:m}),t[14]||(t[14]=n('<h3 id="一、先立条理-再讲道理" tabindex="-1">一、先立条理，再讲道理 <a class="header-anchor" href="#一、先立条理-再讲道理" aria-label="Permalink to &quot;一、先立条理，再讲道理&quot;">​</a></h3><p>渔父开口不是训斥，而是先说「同类相从，同声相应，固天之理也」——同声相应是自然的，所以我要把所懂的讲给你听，再条理你所做的事。</p><p>这一句看似客套，其实定了整段的语气：他说的是「天之理」，不是「我的看法」。后面那些批评之所以有分量，是因为它们被挂在自然条理上，而不是挂在长者的身份上。</p><h3 id="二、四类职分-治之美在「各安其位」" tabindex="-1">二、四类职分：治之美在「各安其位」 <a class="header-anchor" href="#二、四类职分-治之美在「各安其位」" aria-label="Permalink to &quot;二、四类职分：治之美在「各安其位」&quot;">​</a></h3><p>天子、诸侯、大夫、庶人，四类各有其位。「四者自正，治之美也」——治得好不好，先看这四类是否各安其位；一旦「四者离位」，乱就来了。</p><p>接着四段把「忧」写到了极具体的层面：</p><table tabindex="0"><thead><tr><th>位</th><th>所忧</th></tr></thead><tbody><tr><td>庶人</td><td>田荒室露、衣食不足、征赋不属、妻妾不和、长少无序</td></tr><tr><td>大夫</td><td>能不胜任、官事不治、行不清白、群下荒怠、功美不有、爵禄不持</td></tr><tr><td>诸侯</td><td>廷无忠臣、国家昏乱、工技不巧、贡职不美、春秋后伦、不顺天子</td></tr><tr><td>天子有司</td><td>阴阳不和、寒暑不时、诸侯暴乱、礼乐不节、财用穷匮、人伦不饬</td></tr></tbody></table><p>值得注意的是：这四段都不是道德口号，而是可指认的实情——田、衣、赋、禄、贡、财，一条条都落得下去。</p><h3 id="三、越位之问-批评落在「位」-不在「心」" tabindex="-1">三、越位之问：批评落在「位」，不在「心」 <a class="header-anchor" href="#三、越位之问-批评落在「位」-不在「心」" aria-label="Permalink to &quot;三、越位之问：批评落在「位」，不在「心」&quot;">​</a></h3><p>四类之忧说完，渔父把话转到眼前这个人身上：</p><blockquote><p>今子既上无君侯有司之势，而下无大臣职事之官，而擅饰礼乐，选人伦，以化齐民，不泰多事乎！</p></blockquote><p>他并没有说孔子关心天下是错的。他问的是：既没有君侯之势、也没有大臣之官，却擅自修治礼乐、条理人伦、教化百姓——这不是越位了吗？</p><p>这里的分寸要拿准：<strong>批评的对象是「无其位而行其事」，而不是「关心天下」本身。</strong> 若读成「凡无位者皆不应有所作为」，就把一句反问读成了普遍禁令。</p><h3 id="四、八疵-待人接物的八种失当" tabindex="-1">四、八疵：待人接物的八种失当 <a class="header-anchor" href="#四、八疵-待人接物的八种失当" aria-label="Permalink to &quot;四、八疵：待人接物的八种失当&quot;">​</a></h3><p>八疵是两张清单里的第一张，专说待人：</p><table tabindex="0"><thead><tr><th>疵</th><th>所指</th></tr></thead><tbody><tr><td>摠</td><td>不是自己的事却揽来做</td></tr><tr><td>佞</td><td>人不理会，硬要进言</td></tr><tr><td>谄</td><td>揣度人意、顺着说</td></tr><tr><td>谀</td><td>不辨是非一味奉承</td></tr><tr><td>谗</td><td>好说别人坏话</td></tr><tr><td>贼</td><td>挑拨离间、拆人交谊</td></tr><tr><td>慝</td><td>以称誉诈伪败坏他人</td></tr><tr><td>险</td><td>两面讨好，暗中抽取自己所想要的</td></tr></tbody></table><p>八条都是<strong>可以指认的行为</strong>，不是给人贴品格标签。所以渔父紧接着说「此八疵者，外以乱人，内以伤身」——乱的、伤的，都是具体关系与自身。</p><h3 id="五、四患-办事任事的四种患害" tabindex="-1">五、四患：办事任事的四种患害 <a class="header-anchor" href="#五、四患-办事任事的四种患害" aria-label="Permalink to &quot;五、四患：办事任事的四种患害&quot;">​</a></h3><p>第二张清单专说任事：</p><table tabindex="0"><thead><tr><th>患</th><th>所指</th></tr></thead><tbody><tr><td>叨</td><td>好揽大事、变更常规以博功名</td></tr><tr><td>贪</td><td>专断自用、侵夺他人</td></tr><tr><td>很</td><td>见过不改、闻谏更甚</td></tr><tr><td>矜</td><td>只认同自己，以己为高</td></tr></tbody></table><p>与八疵对看：八疵在待人，四患在任事。前者伤关系，后者坏事功。两张清单合起来，才是「可教」的门槛。</p><h3 id="六、而后可教-受教也有前提" tabindex="-1">六、而后可教：受教也有前提 <a class="header-anchor" href="#六、而后可教-受教也有前提" aria-label="Permalink to &quot;六、而后可教：受教也有前提&quot;">​</a></h3><p>全段落在一句不客气的话上：</p><blockquote><p>能去八疵，无行四患，而始可教已。</p></blockquote><p>受教不是只要肯听就行，还得先具备听的条件。这句常被读成傲慢，其实更像一道诚实的门槛：毛病还在，说了也听不进去。</p><p>孔子的回应紧接着就来了——不是辩解，而是「再拜而起」，随后列举自己的困厄请问所失。<strong>门槛立住了，人才真的进来了。</strong></p><h3 id="本份·核心对照-1" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-1" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>立据</td><td>同类相从，同声相应</td><td>进言有自然条理作依据</td><td>凭身份压人</td></tr><tr><td>分职</td><td>四者自正，治之美也</td><td>各安其位则治</td><td>等级不可讨论</td></tr><tr><td>越位</td><td>不泰多事乎</td><td>批评「无位而治」</td><td>一切公共参与皆非</td></tr><tr><td>八疵</td><td>非其事而事之，谓之摠……</td><td>待人的八种失当</td><td>给人贴品格标签</td></tr><tr><td>四患</td><td>好经大事……谓之叨</td><td>任事的四种患害</td><td>与八疵混为一单</td></tr><tr><td>可教</td><td>而始可教已</td><td>受教需要前提</td><td>拿「不可教」拒绝他人</td></tr></tbody></table><h3 id="本份收束-1" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-1" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>渔父这一份说的是「秩序」：四类各有其位，各有其忧；八疵伤关系，四患坏事功。孔子被批评的地方不在于志向，而在于位与事不相称。</p><p>而「而始可教已」一句，把话题从批评转回了学习——<strong>先去掉毛病，才谈得上受教。</strong></p><h2 id="三、困厄追问·畏影恶迹·修身守真" tabindex="-1">三、困厄追问·畏影恶迹·修身守真 <a class="header-anchor" href="#三、困厄追问·畏影恶迹·修身守真" aria-label="Permalink to &quot;三、困厄追问·畏影恶迹·修身守真&quot;">​</a></h2>',32)),a(i,{title:"努力之前，先检验办法",summary:"由孔子的亲身困厄进入畏影恶迹的譬喻，辨认办法与目标的冲突，再看修身守真怎样改变行动的着力点。"}),t[15]||(t[15]=n('<h3 id="本份范围-2" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-2" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“孔子愀然而叹，再拜而起……”</li><li><strong>止于</strong>：“今不修之身而求之人，不亦外乎！”</li><li><strong>连续脉络</strong>：列举困厄 → 追问所失 → 难悟之叹 → 畏影恶迹 → 回看细密经营 → 修身守真 → 点出向外之求。</li></ul><p>第二节说明职分与疵患，提出“而始可教”。本份则从一般教诲转向孔子的亲身遭遇：</p><blockquote><p>听过这些道理，能否由此重新理解自己的行动与困厄？</p></blockquote><h3 id="原文·连续阅读-2" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-2" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',5)),a(s,{sections:l(V),glossary:h,"default-mode":"classic","aria-label":"渔父·第3份 原文"},null,8,["sections"]),t[16]||(t[16]=e("p",null,[e("strong",null,"文字说明")],-1)),t[17]||(t[17]=e("p",null,"原文依据所提供文本整理，调整排版与标点。“四谤”“仁义之间”“还以物与人”等处存在训释空间，以下结合语境说明主要语意，不强定唯一解释。",-1)),t[18]||(t[18]=e("p",null,"孔子所列遭遇在本篇中承担思想论辩的作用；此处不展开各事件的历史核验，也不直接由譬喻确定所有困厄的现实原因。",-1)),t[19]||(t[19]=e("h3",{id:"关键词卡片-2",tabindex:"-1"},[d("关键词卡片 "),e("a",{class:"header-anchor",href:"#关键词卡片-2","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:l(I)},null,8,["items"]),t[20]||(t[20]=e("h3",{id:"核心句引读-2",tabindex:"-1"},[d("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:q}),t[21]||(t[21]=e("h3",{id:"逐句导读-2",tabindex:"-1"},[d("逐句导读 "),e("a",{class:"header-anchor",href:"#逐句导读-2","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:z}),t[22]||(t[22]=n('<h3 id="一、孔子的问题-我不知道自己失在哪里" tabindex="-1">一、孔子的问题：我不知道自己失在哪里 <a class="header-anchor" href="#一、孔子的问题-我不知道自己失在哪里" aria-label="Permalink to &quot;一、孔子的问题：我不知道自己失在哪里&quot;">​</a></h3><p>孔子先列举被逐于鲁、削迹于卫、伐树于宋、围于陈蔡，接着问：</p><blockquote><p>丘不知所失，而离此四谤者何也？</p></blockquote><p>他不是只说“我受了很多苦”，而是把遭遇与自身所失联系起来，寻求解释。困厄已经成为需要重新理解的问题。</p><p>但“我不知道失在哪里”不等于“我已经确认所有困厄都是自己的过错”。原文也没有逐项说明各事件的责任与原因。</p><p><strong>先保留孔子的追问，不用一个总标签替代所有遭遇。</strong></p><h3 id="二、从虚心到领悟-恭敬并未使问题自动解决" tabindex="-1">二、从虚心到领悟：恭敬并未使问题自动解决 <a class="header-anchor" href="#二、从虚心到领悟-恭敬并未使问题自动解决" aria-label="Permalink to &quot;二、从虚心到领悟：恭敬并未使问题自动解决&quot;">​</a></h3><p>前两份中，孔子多次再拜，表示好学与虚心。到这里，渔父却说：</p><blockquote><p>甚矣，子之难悟也！</p></blockquote><table tabindex="0"><thead><tr><th>已经表现出来的</th><th>尚待发生的</th></tr></thead><tbody><tr><td>愿意求教</td><td>真正领会所说</td></tr><tr><td>恭敬听取</td><td>回看自己的行动方式</td></tr><tr><td>提出切身问题</td><td>改变解释困厄的角度</td></tr></tbody></table><p>愿意听，并不等于马上理解。“凄然变容”使责叹带有忧惋意味，而不只是羞辱。</p><p>接下来，渔父不再增加清单，而是换用一个故事。教诲由条目说明转成具体譬喻。</p><h3 id="三、畏影恶迹-目标与办法发生了冲突" tabindex="-1">三、畏影恶迹：目标与办法发生了冲突 <a class="header-anchor" href="#三、畏影恶迹-目标与办法发生了冲突" aria-label="Permalink to &quot;三、畏影恶迹：目标与办法发生了冲突&quot;">​</a></h3><p>譬喻中的人害怕影子，厌恶脚印，于是奔跑，希望摆脱它们。但结果是：</p><blockquote><p>举足愈数而迹愈多，走愈疾而影不离身。</p></blockquote><p>两个问题有所不同：</p><ul><li>脚印因继续迈步而不断增加。</li><li>影子并不因跑得更快而脱离身体。</li></ul><p>因而，奔跑既制造新的脚印，也不能解除影子的追随。所用办法与所求目标并不相合。</p><p>这不是写他不够坚强，或努力得还不够。问题在于：<strong>他以为正在摆脱，实际上却在延续或增加所厌之物。</strong></p><h3 id="四、-自以为尚迟-把办法失当误认成用力不足" tabindex="-1">四、“自以为尚迟”：把办法失当误认成用力不足 <a class="header-anchor" href="#四、-自以为尚迟-把办法失当误认成用力不足" aria-label="Permalink to &quot;四、“自以为尚迟”：把办法失当误认成用力不足&quot;">​</a></h3><p>影子仍在，脚印更多，他却判断：</p><blockquote><p>自以为尚迟。</p></blockquote><p>他没有问“跑是否能解决这个问题”，而只问“是不是还跑得不够快”。于是继续加力，最后“疾走不休，绝力而死”。</p><p><strong>譬喻中的错误循环：</strong></p><p>办法没有奏效 → 把失败解释为努力不足 → 更强地重复原办法 → 问题延续，身体耗尽。</p><p>这可以与第二节“见过不更，闻谏愈甚”联系：不能改变办法，可能使原有问题逐步加重。</p><p>但原文没有把譬喻逐项标为四患中的某一患，不必机械对应。</p><h3 id="五、处阴、处静-不是跑得更快-而是改变条件" tabindex="-1">五、处阴、处静：不是跑得更快，而是改变条件 <a class="header-anchor" href="#五、处阴、处静-不是跑得更快-而是改变条件" aria-label="Permalink to &quot;五、处阴、处静：不是跑得更快，而是改变条件&quot;">​</a></h3><blockquote><p>不知处阴以休影，处静以息迹。</p></blockquote><p>解决方式不再是与影子竞速，而是：</p><ul><li>改变所处环境，使影子不再显现。</li><li>停止奔走，不再产生新脚印。</li></ul><p>关键在改变条件与行动方式。尤其“息迹”不是过去的脚印全部消失，而是停止继续制造新的痕迹。</p><p><strong>引申理解</strong>：有些困扰需要停止追加，而不只是设法追赶、压制。</p><p>但不能推广成“一切问题只要安静不动就能解决”。处静是针对譬喻中特定问题的办法，不是任何处境下的统一答案。</p><h3 id="六、譬喻怎样指回孔子" tabindex="-1">六、譬喻怎样指回孔子？ <a class="header-anchor" href="#六、譬喻怎样指回孔子" aria-label="Permalink to &quot;六、譬喻怎样指回孔子？&quot;">​</a></h3><p>渔父紧接着列举孔子的经营：</p><table tabindex="0"><thead><tr><th>所经营的方面</th><th>原文表达</th></tr></thead><tbody><tr><td>道德关系与分际</td><td>审仁义之间</td></tr><tr><td>判断与界限</td><td>察同异之际</td></tr><tr><td>行动与变化</td><td>观动静之变</td></tr><tr><td>接受、给予的分寸</td><td>适受与之度</td></tr><tr><td>喜好与厌恶</td><td>理好恶之情</td></tr><tr><td>情绪的节度</td><td>和喜怒之节</td></tr></tbody></table><p>这些并不是明显恶行，反而可以显得细密、认真、求其合宜。但渔父紧接着指出：</p><blockquote><p>而几于不免矣。</p></blockquote><p>细密经营，并未自动使孔子免于困厄。譬喻所要动摇的，是“只要更加审察、更加调理、更加用力，就必然能解决问题”的预设。</p><h3 id="七、不是所有审察都错-而是要检验经营的整体方式" tabindex="-1">七、不是所有审察都错，而是要检验经营的整体方式 <a class="header-anchor" href="#七、不是所有审察都错-而是要检验经营的整体方式" aria-label="Permalink to &quot;七、不是所有审察都错，而是要检验经营的整体方式&quot;">​</a></h3><p>本段没有逐项论证仁义必然伤身、分辨同异毫无意义、喜怒无需调节，或接受与给予无需分寸。</p><p>因而，不宜直接推出“一切判断与修养都应停止”。</p><p>结合前后文，批评更集中于：<strong>广泛经营人事，却未把自身修治与守真作为根据。</strong></p><p>不只看有没有认真做事，还要看认真所依凭的方向是否合宜。形式上的周密，不能代替对整体方向的检验。</p><h3 id="八、-谨修而身-慎守其真-把着力点转回自身" tabindex="-1">八、“谨修而身，慎守其真”：把着力点转回自身 <a class="header-anchor" href="#八、-谨修而身-慎守其真-把着力点转回自身" aria-label="Permalink to &quot;八、“谨修而身，慎守其真”：把着力点转回自身&quot;">​</a></h3><blockquote><p>谨修而身，慎守其真。</p></blockquote><p>这不是彻底取消修治。原文仍然要求谨慎修身、慎重守真。</p><p>所改变的是着力点：从不断经营外在关系，转到自身怎样立定、怎样不失其真。</p><p>但“真”尚未在本份中定义。下一份孔子将直接追问“请问何谓真”。</p><p>因而，不能提前把守真解释成：</p><ul><li>想做什么就做什么。</li><li>拒绝所有人伦关系。</li><li>只顾自己的安逸。</li><li>不再接受任何约束。</li></ul><p><strong>本份提出方向，下一份才展开内容。</strong></p><h3 id="九、-还以物与人-放下不必尽由自己承担的经营" tabindex="-1">九、“还以物与人”：放下不必尽由自己承担的经营 <a class="header-anchor" href="#九、-还以物与人-放下不必尽由自己承担的经营" aria-label="Permalink to &quot;九、“还以物与人”：放下不必尽由自己承担的经营&quot;">​</a></h3><blockquote><p>还以物与人，则无所累矣。</p></blockquote><p>这句话有训释空间，通常可以联系把外物、事务还给他人，不再尽由自己揽持理解。</p><p>与第二节相接，它提示：</p><ul><li>他人有自己的事务。</li><li>各种关系不必都由自己安排。</li><li>广泛包揽可能反过来形成牵累。</li></ul><p>但不宜补成把全部财产送人、放弃已经承担的正当责任、任由他人受害，或一概拒绝帮助别人。</p><p><strong>重点在解除不合宜的包揽，不是把任何责任都推开。</strong></p><h3 id="十、-不修之身而求之人-最后点破向外的问题" tabindex="-1">十、“不修之身而求之人”：最后点破向外的问题 <a class="header-anchor" href="#十、-不修之身而求之人-最后点破向外的问题" aria-label="Permalink to &quot;十、“不修之身而求之人”：最后点破向外的问题&quot;">​</a></h3><blockquote><p>今不修之身而求之人，不亦外乎！</p></blockquote><p>问题不只是活动太多，也不只是别人不理解孔子，而是尚未从自身立定，却把求取与经营的重心放在人身上。</p><p>“求之人”可联系向他人求取、求诸他人或着力于他人理解。本段没有将它限定为只求名声、官位或认同。</p><p>可以保留较宽的语意：把解决问题的根据持续放到外在的人与关系中。渔父要求的转向，则是先回看自身。</p><h3 id="十一、阅读限度-不能由譬喻推出受困者应承担全部责任" tabindex="-1">十一、阅读限度：不能由譬喻推出受困者应承担全部责任 <a class="header-anchor" href="#十一、阅读限度-不能由譬喻推出受困者应承担全部责任" aria-label="Permalink to &quot;十一、阅读限度：不能由譬喻推出受困者应承担全部责任&quot;">​</a></h3><p>畏影恶迹具有鲜明的修身劝诫作用，但不是对被逐、受围等事件逐一完成的因果调查。</p><table tabindex="0"><thead><tr><th>本段可以说明</th><th>本段不能直接证明</th></tr></thead><tbody><tr><td>某种行动方式可能加重自身牵累</td><td>所有外部迫害都由受害者造成</td></tr><tr><td>加倍努力未必纠正错误方向</td><td>所有困厄都只需改变自己</td></tr><tr><td>应检省自身的经营方式</td><td>他人的不当行为无需承担责任</td></tr></tbody></table><p>**自我检省与外部责任可以同时存在。**不宜借守真之说，把政治排斥、威胁与围困一概变成孔子的个人过错。</p><h3 id="十二、与《盗跖》《说剑》的进一步对读" tabindex="-1">十二、与《盗跖》《说剑》的进一步对读 <a class="header-anchor" href="#十二、与《盗跖》《说剑》的进一步对读" aria-label="Permalink to &quot;十二、与《盗跖》《说剑》的进一步对读&quot;">​</a></h3><p><strong>与《盗跖》：全身之问仍在，但孔子的回应不同。</strong></p><p>两篇都使孔子的仁义教化面对困厄、伤身、能否保全自身及所行是否合道的问题。</p><p>但《渔父》中，孔子持续追问、再拜求教。批评不仅造成受挫，也推动新问题出现。到本份末尾，“何谓真”已成为下一步必须回答的问题。</p><p><strong>与《说剑》：重复原办法可能延续原问题。</strong></p><p>《说剑》中，赵王因期待庄子试剑而继续校剑，造成新增死伤；这里，畏影恶迹者继续奔跑，反而增加脚印、耗尽自身。</p><p>二者可以共同提示：目标有所变化，不等于办法已经改变。</p><p>但两段不能等同：《说剑》涉及掌权者的喜好与他人生命；本段主要指向行动者自身的经营与牵累。</p><h3 id="本份·核心对照-2" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-2" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>困厄追问</td><td>丘不知所失</td><td>以自身遭遇求解释</td><td>已承认全部困厄都由自己造成</td></tr><tr><td>领悟之难</td><td>子之难悟也</td><td>谦敬与理解不同</td><td>再拜求教毫无意义</td></tr><tr><td>错误办法</td><td>举足愈数而迹愈多</td><td>行动可能制造所厌之物</td><td>所有努力都会加重问题</td></tr><tr><td>错误诊断</td><td>自以为尚迟</td><td>把办法失当误认成用力不足</td><td>失败必然证明不够努力</td></tr><tr><td>改变条件</td><td>处阴以休影，处静以息迹</td><td>不重复无效办法</td><td>任何问题都应静止不动</td></tr><tr><td>人事经营</td><td>审仁义、察同异等</td><td>周密不等于方向合宜</td><td>所有判断与调理都应废除</td></tr><tr><td>修身守真</td><td>谨修而身，慎守其真</td><td>转回自身根据</td><td>真就是任性、退避</td></tr><tr><td>解除包揽</td><td>还以物与人</td><td>不尽揽外在事务</td><td>放弃所有责任</td></tr><tr><td>向外之问</td><td>不修之身而求之人</td><td>检省求取与经营的重心</td><td>改变自己便能消除所有外部问题</td></tr></tbody></table><h3 id="本份收束-2" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-2" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>本段有三步：</p><ol><li>由孔子的困厄，提出“所失何在”。</li><li>以畏影恶迹，说明加倍重复旧办法可能加重问题。</li><li>转向修身守真，不再只从外在的人与关系中求取解决。</li></ol><p>但这一转向留下了尚未回答的核心问题：</p><blockquote><p>所要守护的“真”，究竟是什么？</p></blockquote><p>下一份将通过悲、怒、亲，以及事亲、事君、饮酒、处丧，说明内在精诚怎样表现于外，实际内容又怎样区别于做足形式。</p><h2 id="四、何谓真·精诚与礼俗·受业与辞别" tabindex="-1">四、何谓真·精诚与礼俗·受业与辞别 <a class="header-anchor" href="#四、何谓真·精诚与礼俗·受业与辞别" aria-label="Permalink to &quot;四、何谓真·精诚与礼俗·受业与辞别&quot;">​</a></h2>',86)),a(i,{title:"真诚不只在表态，也在实现",summary:"由“何谓真”进入精诚、真实情感与人事中的功、乐、哀、适，再辨析礼俗的限度及受业请求为何没有转成长期授业关系。"}),t[23]||(t[23]=n('<h3 id="本份范围-3" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-3" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“孔子愀然曰：‘请问何谓真？’”</li><li><strong>止于</strong>：“乃剌船而去，延缘苇间。”</li><li><strong>连续脉络</strong>：追问真 → 精诚作答 → 强作与真实 → 用于人理 → 内容与形式 → 法天贵真 → 请求受业 → 同行条件与辞别。</li></ul><p>第三节提出“慎守其真”，本份进一步回答：</p><blockquote><p>所守的真是什么，又怎样体现于人的关系与行动？</p></blockquote><h3 id="原文·连续阅读-3" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-3" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',5)),a(s,{sections:l(R),glossary:h,"default-mode":"classic","aria-label":"渔父·第4份 原文"},null,8,["sections"]),t[24]||(t[24]=e("p",null,[e("strong",null,"文字说明")],-1)),t[25]||(t[25]=e("p",null,"原文依据所提供文本整理，调整排版与标点。“虽严不屯”“无一其迹”“比之服役”“不可与往者，不知其道”等处，字义或句法有解释空间，不强定唯一训释。",-1)),t[26]||(t[26]=e("p",null,"本段的“真”涉及精诚、情感及其在人伦中的实现，不只按现代“真实消息”或“没有说谎”的意义理解。",-1)),t[27]||(t[27]=e("h3",{id:"关键词卡片-3",tabindex:"-1"},[d("关键词卡片 "),e("a",{class:"header-anchor",href:"#关键词卡片-3","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:l(D)},null,8,["items"]),t[28]||(t[28]=e("h3",{id:"核心句引读-3",tabindex:"-1"},[d("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:c}),t[29]||(t[29]=e("h3",{id:"逐句导读-3",tabindex:"-1"},[d("逐句导读 "),e("a",{class:"header-anchor",href:"#逐句导读-3","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:T}),t[30]||(t[30]=n('<h3 id="一、-何谓真-孔子把教诲中的关键词提出来追问" tabindex="-1">一、“何谓真”：孔子把教诲中的关键词提出来追问 <a class="header-anchor" href="#一、-何谓真-孔子把教诲中的关键词提出来追问" aria-label="Permalink to &quot;一、“何谓真”：孔子把教诲中的关键词提出来追问&quot;">​</a></h3><p>第三节要求“慎守其真”，孔子接着问：</p><blockquote><p>请问何谓真？</p></blockquote><p>他没有把守真当作已经明白的口号，而是要求说明内容。愿意接受一个方向，还需要知道这个方向意味着什么。</p><p>这一追问把前文的职分、疵患与困厄，转向更内在的根据：人怎样不失其真，怎样使所行不只是外在经营。</p><h3 id="二、-精诚之至-真不只是没有说谎" tabindex="-1">二、“精诚之至”：真不只是没有说谎 <a class="header-anchor" href="#二、-精诚之至-真不只是没有说谎" aria-label="Permalink to &quot;二、“精诚之至”：真不只是没有说谎&quot;">​</a></h3><blockquote><p>真者，精诚之至也。<br> 不精不诚，不能动人。</p></blockquote><p>本段的真不限于一句话是否符合事实，还涉及：</p><ul><li>情感是否出于真实。</li><li>行动是否出于精诚。</li><li>内在与外在是否相应。</li><li>是否夹杂勉强制造的表现。</li></ul><p>因而，不能概括成“只要不撒谎，就已经守真”。</p><p>同时，“不能动人”不宜反过来理解为“只要能感动别人，就一定是真的”。虚假表现也可能一时打动人。</p><p><strong>本段以动人说明精诚的力量，并未提供识别所有真伪的唯一测试。</strong></p><h3 id="三、强哭、强怒、强亲-做出表现-不等于实现内容" tabindex="-1">三、强哭、强怒、强亲：做出表现，不等于实现内容 <a class="header-anchor" href="#三、强哭、强怒、强亲-做出表现-不等于实现内容" aria-label="Permalink to &quot;三、强哭、强怒、强亲：做出表现，不等于实现内容&quot;">​</a></h3><table tabindex="0"><thead><tr><th>外在表现</th><th>原文指出的不足</th></tr></thead><tbody><tr><td>强哭</td><td>虽悲不哀</td></tr><tr><td>强怒</td><td>虽严不屯</td></tr><tr><td>强亲</td><td>虽笑不和</td></tr></tbody></table><p>三者分别涉及悲伤、愤怒与亲近。共同问题是：可以做出相应动作，却未必有真实情感及其感发作用。</p><p>哭、严厉、微笑，本身不是假的。<strong>“强”才是关键</strong>：为呈现某种样子而勉强制造，内在却没有相应内容。</p><p>不宜读成哭得出来就是虚伪、表情严肃就是造作，或对人微笑就是不真。</p><h3 id="四、真悲、真怒、真亲-内容不以外在动作完成为前提" tabindex="-1">四、真悲、真怒、真亲：内容不以外在动作完成为前提 <a class="header-anchor" href="#四、真悲、真怒、真亲-内容不以外在动作完成为前提" aria-label="Permalink to &quot;四、真悲、真怒、真亲：内容不以外在动作完成为前提&quot;">​</a></h3><blockquote><p>真悲无声而哀，真怒未发而威，真亲未笑而和。</p></blockquote><table tabindex="0"><thead><tr><th>真实内容</th><th>不必先具备的外在表现</th></tr></thead><tbody><tr><td>真悲</td><td>不必先有哭声</td></tr><tr><td>真怒</td><td>不必先发作</td></tr><tr><td>真亲</td><td>不必先微笑</td></tr></tbody></table><p>这一对照不是要求不哭、不怒、不笑，而是说明外在动作不是情感真实的必要凭证。</p><p>真实悲哀可以沉默，真实亲近也可以不靠刻意笑容。真怒尚未发作，也可以有严肃的感发力。</p><p>但这不是赞许所有愤怒，更不是认可伤害他人。<strong>情感是否真实，与表达方式是否合宜，仍需分开判断。</strong></p><h3 id="五、-真在内者-神动于外-内外不是彼此隔绝" tabindex="-1">五、“真在内者，神动于外”：内外不是彼此隔绝 <a class="header-anchor" href="#五、-真在内者-神动于外-内外不是彼此隔绝" aria-label="Permalink to &quot;五、“真在内者，神动于外”：内外不是彼此隔绝&quot;">​</a></h3><blockquote><p>真在内者，神动于外，是所以贵真也。</p></blockquote><p>这里没有把内外切成“内在都真、外在都假”。相反，真实在内，会表现、感发于外。</p><p>关键不是取消表现，而是外在表现有没有内在精诚作为根据。</p><p>同样的哭、笑、礼貌动作，可能出于真实，也可能出于勉强造作。只看动作是否出现，不足以判断真伪。</p><p>这一点也为篇末孔子的再拜与恭敬留下理解空间。</p><h3 id="六、-其用于人理-贵真并未取消人伦关系" tabindex="-1">六、“其用于人理”：贵真并未取消人伦关系 <a class="header-anchor" href="#六、-其用于人理-贵真并未取消人伦关系" aria-label="Permalink to &quot;六、“其用于人理”：贵真并未取消人伦关系&quot;">​</a></h3><p>渔父将真放进事亲、事君、饮酒与处丧四类事务。</p><p>这说明守真不是一概退出亲属、政治、交往与丧事。第三节要求从向外经营转回自身，并不等于以后不再与人发生关系。</p><p>更准确的是：<strong>人在关系中行动，要有真实的根据，而非只完成一种规定的样子。</strong></p><p>不能把贵真等同于“我只管自己的感受，其他关系都不重要”。</p><h3 id="七、四类事务-分别以什么为主" tabindex="-1">七、四类事务：分别以什么为主？ <a class="header-anchor" href="#七、四类事务-分别以什么为主" aria-label="Permalink to &quot;七、四类事务：分别以什么为主？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事务</th><th>所应体现</th><th>主要依据</th><th>不应拘定之处</th></tr></thead><tbody><tr><td>事君</td><td>忠贞</td><td>功：实际事务的成就</td><td>功成不限定一种行迹</td></tr><tr><td>饮酒</td><td>欢乐</td><td>乐：真实的欢乐</td><td>不拘特定器具</td></tr><tr><td>处丧</td><td>悲哀</td><td>哀：真实的哀感</td><td>不以特定礼仪形式为首要凭证</td></tr><tr><td>事亲</td><td>慈孝</td><td>适：合宜照料、安顿亲人</td><td>不限定单一办法</td></tr></tbody></table><p>这不只是情绪真假，还涉及事务有没有实现所应实现的内容。</p><p>特别是事亲与事君：孝不只靠表示孝顺，忠不只靠表示忠诚；还要看亲人是否得到合宜照料，事务是否实际有所成就。</p><h3 id="八、-无一其迹-内容可以通过不同方式实现" tabindex="-1">八、“无一其迹”：内容可以通过不同方式实现 <a class="header-anchor" href="#八、-无一其迹-内容可以通过不同方式实现" aria-label="Permalink to &quot;八、“无一其迹”：内容可以通过不同方式实现&quot;">​</a></h3><blockquote><p>功成之美，无一其迹矣。</p></blockquote><p>这句话通常联系成就事务的方式不必只有一种理解。后面进一步展开：</p><ul><li>事亲重适，不限定同一种办法。</li><li>饮酒重乐，不拘定同一种器具。</li><li>处丧重哀，不以礼仪完成替代哀感。</li></ul><p>本段不是简单反对一切形式，而是反对把固定形式当成实现内容的唯一道路。</p><p>**不拘一种办法，也不意味着任何办法都合宜。**仍须回到功、乐、哀、适的具体内容检验。</p><h3 id="九、-礼者-世俗之所为-礼俗不应替代真实" tabindex="-1">九、“礼者，世俗之所为”：礼俗不应替代真实 <a class="header-anchor" href="#九、-礼者-世俗之所为-礼俗不应替代真实" aria-label="Permalink to &quot;九、“礼者，世俗之所为”：礼俗不应替代真实&quot;">​</a></h3><blockquote><p>礼者，世俗之所为也；真者，所以受于天也，自然不可易也。</p></blockquote><table tabindex="0"><thead><tr><th>礼</th><th>真</th></tr></thead><tbody><tr><td>世俗所制定、形成的规范与形式</td><td>禀受于天、天然所具的真实</td></tr><tr><td>可因社会习惯形成不同样式</td><td>不应被俗习任意扭曲、替换</td></tr><tr><td>容易成为外在判断依据</td><td>是外在表达所应依据的内在内容</td></tr></tbody></table><p>本段确实对礼俗提出鲜明批评，不能淡化成一般的形式灵活。</p><p>但也不宜直接概括为“所有礼仪都必须废除”。后文孔子仍将以敬长、尊贤、礼与仁解释自己的行动，须留到第五节合读。</p><p>此处先把握：<strong>礼俗不能因被普遍遵循，就自动压过真实内容。</strong></p><h3 id="十、-法天贵真-不拘于俗-反对被俗习牵引而失真" tabindex="-1">十、“法天贵真，不拘于俗”：反对被俗习牵引而失真 <a class="header-anchor" href="#十、-法天贵真-不拘于俗-反对被俗习牵引而失真" aria-label="Permalink to &quot;十、“法天贵真，不拘于俗”：反对被俗习牵引而失真&quot;">​</a></h3><p>渔父对照圣人与愚者：</p><ul><li>圣人法天贵真，不拘于俗。</li><li>愚者不能法天，反而顾虑他人、受俗改变。</li></ul><p>“恤于人”在这里不是否定关怀他人，而是着重说明过度以他人的眼光与世俗评价安排自己。</p><p>“受变于俗”则意味着应守护的真实被习惯、期待与评价牵引。</p><p>但不能将自然直接等同于任何冲动：“我有这个欲望，所以照做就是法天。”</p><p>本段的真以精诚为核心，并在人事中以功、乐、哀、适展开。<strong>自然不是为任性提供免于检验的理由。</strong></p><h3 id="十一、-蚤湛于伪-渔父的批评比第一节更深入" tabindex="-1">十一、“蚤湛于伪”：渔父的批评比第一节更深入 <a class="header-anchor" href="#十一、-蚤湛于伪-渔父的批评比第一节更深入" aria-label="Permalink to &quot;十一、“蚤湛于伪”：渔父的批评比第一节更深入&quot;">​</a></h3><p>第一节说“仁则仁矣，恐不免其身”，此处则说：</p><blockquote><p>惜哉，子之蚤湛于伪而晚闻大道也！</p></blockquote><p>批评由行动代价，深入到孔子是否长期被人为造作与俗习牵引。</p><p>“伪”不必全部理解成蓄意欺骗。即使主观上有仁心，也可能依惯常形式行动，逐渐以形式替代真实。</p><p>这与前文不必然矛盾：有仁心，仍可能在实现仁心的方式上失真。</p><p>但这是渔父对孔子的判断，不宜扩展成对孔子全部思想与生平的历史定论。</p><h3 id="十二、孔子求受业-一次相遇尚不足以完成学习" tabindex="-1">十二、孔子求受业：一次相遇尚不足以完成学习 <a class="header-anchor" href="#十二、孔子求受业-一次相遇尚不足以完成学习" aria-label="Permalink to &quot;十二、孔子求受业：一次相遇尚不足以完成学习&quot;">​</a></h3><p>孔子听后再拜，认为这次相遇仿佛天赐之幸，进一步问渔父住在哪里，希望继续受业、学习大道。</p><p>求教由“请解释先前的话”，转成“希望继续跟随学习”。</p><p>孔子没有因为听过一次说明，就宣称自己已经得道。理解一个概念，不等于完成其践行。</p><p>但这仍是孔子的请求，不是已经建立的师徒关系。</p><h3 id="十三、-可与往-与-不可与往-同行需要条件" tabindex="-1">十三、“可与往”与“不可与往”：同行需要条件 <a class="header-anchor" href="#十三、-可与往-与-不可与往-同行需要条件" aria-label="Permalink to &quot;十三、“可与往”与“不可与往”：同行需要条件&quot;">​</a></h3><blockquote><p>可与往者，与之至于妙道；不可与往者，不知其道。<br> 慎勿与之，身乃无咎。</p></blockquote><p>具体句法有解释空间，基本方向是：能否共同进于道，需要辨别，不能勉强同行。</p><p>这照应第二节“而始可教”：学习不只在一方愿意说，还在另一方能否相应、能否继续前进。</p><p>然而，原文没有明确宣布：</p><ul><li>孔子完全不可教。</li><li>孔子已经完全合格。</li><li>渔父将来一定继续授业。</li></ul><p><strong>渔父说明同行的条件，却没有明确承诺长期相从。</strong></p><h3 id="十四、重复辞别-渔父没有留下可继续依附的安排" tabindex="-1">十四、重复辞别：渔父没有留下可继续依附的安排 <a class="header-anchor" href="#十四、重复辞别-渔父没有留下可继续依附的安排" aria-label="Permalink to &quot;十四、重复辞别：渔父没有留下可继续依附的安排&quot;">​</a></h3><blockquote><p>子勉之，吾去子矣，吾去子矣！</p></blockquote><p>渔父鼓励孔子自勉，重复说明自己将离去，随后撑船，沿芦苇间离开。</p><p>故事没有写他留下住址，也没有写孔子再次追船。教诲已经发生，长期受业却未在叙事中建立。</p><p><strong>结构上的理解</strong>：孔子不能只把学习的根据寄托在持续追随渔父上，还需要自己实行修身守真。</p><p>但不必补写成渔父明确设计了一场教学考验。他的离去，保留了这场相遇的开放性与限度。</p><h3 id="十五、与前三份的连续照应" tabindex="-1">十五、与前三份的连续照应 <a class="header-anchor" href="#十五、与前三份的连续照应" aria-label="Permalink to &quot;十五、与前三份的连续照应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>前文提出</th><th>本份展开</th></tr></thead><tbody><tr><td>苦心劳形以危其真</td><td>真以精诚说明，不只是外在经营</td></tr><tr><td>去八疵，无行四患</td><td>迎合、造作、自用与真实的关系更清楚</td></tr><tr><td>慎守其真</td><td>真在人事中体现为功、乐、哀、适</td></tr><tr><td>不修之身而求之人</td><td>贵真不应被他人评价与俗习牵引</td></tr><tr><td>孔子主动追寻</td><td>孔子希望继续受业，渔父却辞别</td></tr></tbody></table><p>本份将先前的危真、守真落实为情感与事务中的具体判断。</p><p>同时留下下一份的问题：</p><blockquote><p>孔子对渔父的恭敬，是拘于礼俗，还是出于真实的尊敬？</p></blockquote><p>子路将在篇末提出自己的疑问。</p><h3 id="本份·核心对照-3" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-3" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>追问</td><td>请问何谓真</td><td>不把关键词当作已懂的口号</td><td>听见守真便已理解</td></tr><tr><td>定义</td><td>精诚之至</td><td>内在精诚与真实表现</td><td>真只是不撒谎</td></tr><tr><td>强作表现</td><td>强哭、强怒、强亲</td><td>动作不必然具有真实内容</td><td>哭、怒、笑本身都是假的</td></tr><tr><td>真实感发</td><td>无声而哀、未发而威、未笑而和</td><td>内容不以做足动作作凭证</td><td>情感真实便可任意表达</td></tr><tr><td>内外关系</td><td>真在内者，神动于外</td><td>外在可表达内在真实</td><td>内在都真、外在都假</td></tr><tr><td>人伦应用</td><td>其用于人理也</td><td>贵真仍在人际事务中实行</td><td>守真就是退出一切关系</td></tr><tr><td>事务标准</td><td>功、乐、哀、适</td><td>实际内容优先于固定样式</td><td>主观自称真诚就够了</td></tr><tr><td>不拘行迹</td><td>无一其迹</td><td>合宜内容可有不同实现方式</td><td>任何方式都可接受</td></tr><tr><td>礼与真</td><td>不拘于俗</td><td>礼俗不能压过真实</td><td>必须废除所有礼仪</td></tr><tr><td>受业请求</td><td>请因受业</td><td>希望继续学习</td><td>已建立长期师徒关系</td></tr><tr><td>同行条件</td><td>可与往、不可与往</td><td>受教与相从不能勉强</td><td>已判定孔子绝不可教</td></tr><tr><td>辞别</td><td>吾去子矣</td><td>相遇结束，践行仍待继续</td><td>已保证以后授业</td></tr></tbody></table><h3 id="本份收束-3" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-3" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>本段对真的说明有三层：</p><ol><li><strong>内在根据</strong>：真以精诚为根据，不是勉强造出某种样子。</li><li><strong>外在表现</strong>：真会表现于外，但不以固定动作作为唯一凭证。</li><li><strong>人事实现</strong>：真用于人事，需要实现功、乐、哀、适等实际内容，而不被礼俗形式替代。</li></ol><p>孔子由此请求继续学习，渔父却离去。故事没有止于大道的解释，还要回到孔子与弟子的关系。</p><p>下一份，子路将问：渔父没有显赫身份，为什么受到这样的恭敬？</p><p>孔子的回答会使本篇最后落到：<strong>尊敬的根据是什么，礼仁与贵真又怎样相接。</strong></p><h2 id="五、子路质疑·孔子答问·尊贤与尊道" tabindex="-1">五、子路质疑·孔子答问·尊贤与尊道 <a class="header-anchor" href="#五、子路质疑·孔子答问·尊贤与尊道" aria-label="Permalink to &quot;五、子路质疑·孔子答问·尊贤与尊道&quot;">​</a></h2>',97)),a(i,{title:"为什么敬，是否真敬",summary:"由孔子离别后的等待进入子路的质疑，再看敬长、尊贤、精诚谦下与尊道怎样构成恭敬的根据。"}),t[31]||(t[31]=n('<h3 id="本份范围-4" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-4" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“颜渊还车，子路授绥……”</li><li><strong>止于</strong>：“吾敢不敬乎！”</li><li><strong>连续脉络</strong>：渔父离去 → 孔子等待 → 子路比较 → 质疑恭敬 → 难化之叹 → 敬长尊贤 → 精诚谦下 → 尊道作答。</li></ul><p>第三节中，渔父强调精诚与贵真，并辞别而去。本份回到具体行动：</p><blockquote><p>孔子的再拜、曲身与等待，究竟应当怎样理解？</p></blockquote><h3 id="原文·连续阅读-4" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-4" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',5)),a(s,{sections:l(N),glossary:h,"default-mode":"classic","aria-label":"渔父·第5份 原文"},null,8,["sections"]),t[32]||(t[32]=e("p",null,[e("strong",null,"文字说明")],-1)),t[33]||(t[33]=e("p",null,"原文依据所提供文本整理，调整排版与标点。“如此其威”“湛于礼义有间”“彼非至人，不能下人”“故长伤身”等处，需要结合上下文理解，不只按现代常用义直译。",-1)),t[34]||(t[34]=e("p",null,"孔子对渔父的评价，是篇末人物的判断与叙事收束，不据此补写孔子已经完全得道或完成全部修养。",-1)),t[35]||(t[35]=e("h3",{id:"关键词卡片-4",tabindex:"-1"},[d("关键词卡片 "),e("a",{class:"header-anchor",href:"#关键词卡片-4","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:l(E)},null,8,["items"]),t[36]||(t[36]=e("h3",{id:"核心句引读-4",tabindex:"-1"},[d("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:k}),t[37]||(t[37]=e("h3",{id:"逐句导读-4",tabindex:"-1"},[d("逐句导读 "),e("a",{class:"header-anchor",href:"#逐句导读-4","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:_}),t[38]||(t[38]=n('<h3 id="一、渔父已经离去-孔子的恭敬仍未结束" tabindex="-1">一、渔父已经离去，孔子的恭敬仍未结束 <a class="header-anchor" href="#一、渔父已经离去-孔子的恭敬仍未结束" aria-label="Permalink to &quot;一、渔父已经离去，孔子的恭敬仍未结束&quot;">​</a></h3><p>颜渊转车，子路递上登车的绳带。孔子没有立即上车，而是：</p><blockquote><p>待水波定，不闻拏音而后敢乘。</p></blockquote><p>恭敬延续到对方离开之后。渔父已渐远，无法继续当面回应，孔子仍郑重等待。</p><p>在叙事上，这使敬意显得持续而深切。但不能把一个动作当成验证内心真实的绝对证据。</p><p><strong>故事通过行动呈现敬意，其根据还要由后面的问答说明。</strong></p><h3 id="二、子路以长期随侍的经验提出疑问" tabindex="-1">二、子路以长期随侍的经验提出疑问 <a class="header-anchor" href="#二、子路以长期随侍的经验提出疑问" aria-label="Permalink to &quot;二、子路以长期随侍的经验提出疑问&quot;">​</a></h3><blockquote><p>由得为役久矣……</p></blockquote><p>子路从熟悉老师的经验作比较。他确实观察到：孔子这一次面对渔父的姿态，与平常面对君主时很不相同。</p><p>因而，这不是一般的无端冒犯。故事让这一差异成为问题，要求孔子说明。</p><p>即使行动显得郑重，旁观者仍可能不明白它的理由。</p><h3 id="三、君主与渔父-子路所用的比较尺度" tabindex="-1">三、君主与渔父：子路所用的比较尺度 <a class="header-anchor" href="#三、君主与渔父-子路所用的比较尺度" aria-label="Permalink to &quot;三、君主与渔父：子路所用的比较尺度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>面对君主</th><th>面对渔父</th></tr></thead><tbody><tr><td>万乘之主、千乘之君</td><td>持桨站立的渔父</td></tr><tr><td>分庭伉礼</td><td>曲要磬折</td></tr><tr><td>仍有倨傲之容</td><td>拜而应答，表现深切敬畏</td></tr></tbody></table><p>前一组突出政治身份与权势，后一组是没有显赫官爵的来者。</p><p>子路问“渔父何以得此乎”，但也问“得无太甚乎”。因此，本段有两个问题：</p><ol><li>尊敬应当依据什么？</li><li>为什么这一次表现得如此深切？</li></ol><p><strong>不能只读身份差异，而忽略恭敬程度的疑问。</strong></p><h3 id="四、-门人皆怪-个人疑问成为师生之间的解释问题" tabindex="-1">四、“门人皆怪”：个人疑问成为师生之间的解释问题 <a class="header-anchor" href="#四、-门人皆怪-个人疑问成为师生之间的解释问题" aria-label="Permalink to &quot;四、“门人皆怪”：个人疑问成为师生之间的解释问题&quot;">​</a></h3><blockquote><p>门人皆怪夫子矣。</p></blockquote><p>这是子路对其他弟子反应的转述，原文没有逐一写出所有弟子的想法。</p><p>但它使孔子的行动不再只需向子路一个人说明。弟子熟悉老师的礼义实践，却未必理解此次敬人的根据。</p><p>全篇由此形成角色转换：</p><ul><li>前面，孔子向渔父求教。</li><li>后面，孔子向弟子说明为何受教、为何敬重来者。</li></ul><p>受教者重新成为解释者，所解释的正是这次相遇。</p><h3 id="五、-难化-照应-难悟-学习是否改变原有判断" tabindex="-1">五、“难化”照应“难悟”：学习是否改变原有判断？ <a class="header-anchor" href="#五、-难化-照应-难悟-学习是否改变原有判断" aria-label="Permalink to &quot;五、“难化”照应“难悟”：学习是否改变原有判断？&quot;">​</a></h3><p>第三节渔父说：</p><blockquote><p>甚矣，子之难悟也！</p></blockquote><p>此处孔子说：</p><blockquote><p>甚矣，由之难化也！</p></blockquote><p>两句形成照应。不能据此断定孔子已经达到与渔父完全相同的境界。</p><p>但在叙事上，孔子开始把受教中的提醒转向弟子：长期学习，不等于原有判断已经转变。</p><p>孔子需要重新理解自身的经营方式；子路也需要重新理解礼义学习是否改变了自己看待他人的尺度。</p><h3 id="六、-湛于礼义-与-朴鄙之心-熟悉规范不等于理解其精神" tabindex="-1">六、“湛于礼义”与“朴鄙之心”：熟悉规范不等于理解其精神 <a class="header-anchor" href="#六、-湛于礼义-与-朴鄙之心-熟悉规范不等于理解其精神" aria-label="Permalink to &quot;六、“湛于礼义”与“朴鄙之心”：熟悉规范不等于理解其精神&quot;">​</a></h3><p>“朴鄙”在此是批评见识与理解尚未转变，不是称赞自然质朴。</p><table tabindex="0"><thead><tr><th>外在学习经历</th><th>尚未完成的转变</th></tr></thead><tbody><tr><td>礼义学得很久</td><td>敬人的根据仍未明白</td></tr><tr><td>熟悉交往姿态</td><td>难理解不同身份者为何值得尊重</td></tr><tr><td>长期随侍老师</td><td>未必理解此次行动</td></tr></tbody></table><p>时间与熟练，不能替代实际领会。这回应第一节孔子长期修学仍须虚心的表态：</p><p><strong>旧学不是免于再学的资格。</strong></p><h3 id="七、孔子没有废弃礼仁-而是用礼仁解释恭敬" tabindex="-1">七、孔子没有废弃礼仁，而是用礼仁解释恭敬 <a class="header-anchor" href="#七、孔子没有废弃礼仁-而是用礼仁解释恭敬" aria-label="Permalink to &quot;七、孔子没有废弃礼仁，而是用礼仁解释恭敬&quot;">​</a></h3><blockquote><p>夫遇长不敬，失礼也；见贤不尊，不仁也。</p></blockquote><p>孔子提出两种根据：敬长、尊贤。二者都不同于政治权势。</p><p>渔父没有显赫官位，并不妨碍他作为长者、贤者受到尊重。孔子也没有因渔父批评礼俗，就宣布礼、仁无用。</p><p>这须与第三节合读：不拘于俗，不等于取消所有礼貌；贵真，也不等于不再敬人。</p><h3 id="八、前文批评礼俗-篇末又讲礼仁-怎样合读" tabindex="-1">八、前文批评礼俗，篇末又讲礼仁，怎样合读？ <a class="header-anchor" href="#八、前文批评礼俗-篇末又讲礼仁-怎样合读" aria-label="Permalink to &quot;八、前文批评礼俗，篇末又讲礼仁，怎样合读？&quot;">​</a></h3><p>这里存在真实的表达张力，不能完全抹平。</p><table tabindex="0"><thead><tr><th>渔父所批评</th><th>孔子此处所说明</th></tr></thead><tbody><tr><td>以固定礼俗替代真实内容</td><td>因对方值得尊敬而表现恭敬</td></tr><tr><td>被俗习与他人评价牵引</td><td>不以显赫权位作为唯一尺度</td></tr><tr><td>有形式而缺乏精诚</td><td>谦下还须精诚，才能得真</td></tr></tbody></table><p>据此可以理解：礼的动作既可能表达真实，也可能成为拘束真实的形式。</p><p>但原文没有系统论证各种礼制如何保留、如何改变，不能据篇末几句话就说渔父与孔子的礼论完全一致。</p><p><strong>结尾提供相接的可能，也保留表达上的差异。</strong></p><h3 id="九、-彼非至人-不能下人-谦下不是低身份" tabindex="-1">九、“彼非至人，不能下人”：谦下不是低身份 <a class="header-anchor" href="#九、-彼非至人-不能下人-谦下不是低身份" aria-label="Permalink to &quot;九、“彼非至人，不能下人”：谦下不是低身份&quot;">​</a></h3><blockquote><p>彼非至人，不能下人。</p></blockquote><p>通常可以理解为：不是达到高度修养的人，就不能真正谦下于人。</p><p>“下人”是动词性的表达，不是所谓下等人，更不是“至人不能与下等人交往”。</p><p>它要求放下自高的姿态，承认他人的所得。有弟子、有学问、有名声，并不妨碍向一个渔父求教。</p><p>但这也不是孔子直接宣布自己就是至人，而是在说明真正谦下需要何种修养。</p><h3 id="十、-下人不精-不得其真-谦下也可能成为表演" tabindex="-1">十、“下人不精，不得其真”：谦下也可能成为表演 <a class="header-anchor" href="#十、-下人不精-不得其真-谦下也可能成为表演" aria-label="Permalink to &quot;十、“下人不精，不得其真”：谦下也可能成为表演&quot;">​</a></h3><p>弯腰、再拜、口称先生，并不自动完成真实的敬重。</p><table tabindex="0"><thead><tr><th>表现</th><th>仍须追问</th></tr></thead><tbody><tr><td>哭</td><td>是否真哀？</td></tr><tr><td>笑</td><td>是否真亲？</td></tr><tr><td>弯腰再拜</td><td>是否真敬、真能下人？</td></tr></tbody></table><p>“下人不精，不得其真”把篇末的谦下与前文精诚连接起来。</p><p>因而，结尾不是把外在礼貌恢复为不可质疑的标准。<strong>礼貌本身也要回到真来检验。</strong></p><p>“故长伤身”又照应开篇“不免其身”“危其真”，得真与伤身的问题贯穿至此。</p><h3 id="十一、责叹子路-修辞强调不是事实统计" tabindex="-1">十一、责叹子路：修辞强调不是事实统计 <a class="header-anchor" href="#十一、责叹子路-修辞强调不是事实统计" aria-label="Permalink to &quot;十一、责叹子路：修辞强调不是事实统计&quot;">​</a></h3><blockquote><p>不仁之于人也，祸莫大焉，而由独擅之。</p></blockquote><p>语气严厉，着重指出子路不能尊贤的问题。“独擅之”不必理解成全天下只有子路不仁。</p><p>同样，本段不意味着：</p><ul><li>子路过去的一切实践都无价值。</li><li>一次疑问足以裁定其全部品格。</li><li>弟子只能服从，不得发问。</li></ul><p>故事让子路发问，并由孔子展开回答。被批评的是他所依凭的判断与理解，不是提问本身。</p><h3 id="十二、-道者-万物之所由-尊敬的根据进一步扩大" tabindex="-1">十二、“道者，万物之所由”：尊敬的根据进一步扩大 <a class="header-anchor" href="#十二、-道者-万物之所由-尊敬的根据进一步扩大" aria-label="Permalink to &quot;十二、“道者，万物之所由”：尊敬的根据进一步扩大&quot;">​</a></h3><blockquote><p>且道者，万物之所由也。</p></blockquote><p>孔子以生死、成败强调道的重要：</p><ul><li>失之者死，得之者生。</li><li>逆之则败，顺之则成。</li></ul><p>尊敬的理由由年龄与才德进一步转向道的根本性。</p><p>但不能将这些句子变成简易的现实判定：</p><ul><li>成功者必然得道。</li><li>失败者必然失道。</li><li>长寿者必然修养更高。</li><li>遭遇灾祸者必然逆道。</li></ul><p><strong>本段强调道的根本性，不是对所有现实结果逐项归因。</strong></p><h3 id="十三、-道之所在-权位不是尊敬的唯一依据" tabindex="-1">十三、“道之所在”：权位不是尊敬的唯一依据 <a class="header-anchor" href="#十三、-道之所在-权位不是尊敬的唯一依据" aria-label="Permalink to &quot;十三、“道之所在”：权位不是尊敬的唯一依据&quot;">​</a></h3><blockquote><p>故道之所在，圣人尊之。</p></blockquote><p>孔子认为渔父“于道，可谓有矣”，因此回答“吾敢不敬乎”。</p><p>敬重的根据，是渔父于道有所得，不只是社会等级中的位置。</p><table tabindex="0"><thead><tr><th>第二节</th><th>第五节</th></tr></thead><tbody><tr><td>办事须检省职分与位置</td><td>敬人不只依据显赫位置</td></tr><tr><td>不宜任意侵越他人事务</td><td>不宜因人无显位而忽略其所得</td></tr></tbody></table><p><strong>责任分配与尊敬根据，不是同一个问题。</strong></p><p>不能因职分论而说无官者都不值得听取，也不能因尊道而说一切职分边界都已取消。</p><h3 id="十四、首尾照应-从-何治-到-何以得此" tabindex="-1">十四、首尾照应：从“何治”到“何以得此” <a class="header-anchor" href="#十四、首尾照应-从-何治-到-何以得此" aria-label="Permalink to &quot;十四、首尾照应：从“何治”到“何以得此”&quot;">​</a></h3><table tabindex="0"><thead><tr><th>开篇</th><th>篇末</th></tr></thead><tbody><tr><td>渔父问“孔氏者何治也”</td><td>子路问“渔父何以得此乎”</td></tr><tr><td>孔子是被介绍、被评价者</td><td>渔父是被说明、被尊敬者</td></tr><tr><td>弟子列举孔子所行与目标</td><td>孔子说明渔父于道有所得</td></tr></tbody></table><p>全篇形成角色变化：</p><p><strong>被评论者 → 主动求教者 → 向弟子解释相遇的意义者。</strong></p><p>结尾不仅呈现渔父的影响，也展示孔子如何重新说明敬人与学习。</p><h3 id="十五、与《盗跖》《说剑》的收束对读" tabindex="-1">十五、与《盗跖》《说剑》的收束对读 <a class="header-anchor" href="#十五、与《盗跖》《说剑》的收束对读" aria-label="Permalink to &quot;十五、与《盗跖》《说剑》的收束对读&quot;">​</a></h3><p><strong>与《盗跖》：受批评后怎样结束？</strong></p><p>《盗跖》第一场以孔子受挫离开收束；《渔父》在离别之后继续写孔子对弟子的解释。</p><p>批评的结果不只表现为离场，也表现为如何理解这场相遇。但不能据此认定孔子已经解决全部问题。</p><p><strong>与《说剑》：结尾行动不等于完整效果已验证。</strong></p><p>《说剑》写赵王表现改变，也留下剑士死亡的问题；《渔父》写孔子说明敬道的根据，却没有展开长期修养的结果。</p><p>故事明确呈现的转变，与读者期待的完整成效，应当分开。</p><h3 id="本份·核心对照-4" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-4" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>离去后的等待</td><td>待水波定，不闻拏音</td><td>敬意延续到当面交往之外</td><td>一个动作足以绝对证明真诚</td></tr><tr><td>子路比较</td><td>万乘之主、千乘之君</td><td>熟悉的权位与交往尺度</td><td>子路只是无端挑衅</td></tr><tr><td>恭敬之问</td><td>得无太甚乎</td><td>根据与程度都需解释</td><td>只问身份，不问行动</td></tr><tr><td>学习之难</td><td>由之难化也</td><td>久学不等于判断已转变</td><td>全部旧学都无价值</td></tr><tr><td>礼仁回答</td><td>遇长敬，见贤尊</td><td>敬人不只依据权势</td><td>贵真等于废除所有礼</td></tr><tr><td>谦下</td><td>不能下人</td><td>放下自高，承认他人所得</td><td>下人指身份低的人</td></tr><tr><td>精诚</td><td>下人不精，不得其真</td><td>礼貌也须检验真实内容</td><td>再拜自动等于真敬</td></tr><tr><td>道的根本性</td><td>万物之所由</td><td>尊道的理由</td><td>现实成败可简单判定得道失道</td></tr><tr><td>最终根据</td><td>道之所在，圣人尊之</td><td>超出显位而敬有道者</td><td>所有职分边界因此取消</td></tr><tr><td>故事结果</td><td>吾敢不敬乎</td><td>孔子说明相遇的意义</td><td>已全面完成修养</td></tr></tbody></table><h3 id="本份收束-4" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-4" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>孔子尊敬渔父，不只因为他年长，更因为孔子认为他于道有所得。这种敬意要能谦下，也要出于精诚。</p><p>全篇不是简单把礼与真对立起来：外在礼貌可以表达真实，固定形式也可能遮蔽真实。</p><p>要检验的是：</p><ul><li>为什么敬？</li><li>是否真敬？</li><li>能否由敬重转为受教？</li><li>所学是否改变自己的判断？</li></ul><p>分段阅读至此结束。以下统合职分与尊贤、贵真与礼仁、修身与人事，以及听学与转变。</p><h2 id="全篇脉络·五份阅读地图" tabindex="-1">全篇脉络·五份阅读地图 <a class="header-anchor" href="#全篇脉络·五份阅读地图" aria-label="Permalink to &quot;全篇脉络·五份阅读地图&quot;">​</a></h2>',102)),a(i,{title:"总读导引｜从所事到所据，从听见到改变",summary:"全篇由人物所治与政治位置进入行动方式，再以精诚说明真，最后追问尊敬与受教的根据。总读保留人物判断、叙事行动与引申解释之间的区别。"}),t[39]||(t[39]=n('<h3 id="整理说明" tabindex="-1">整理说明 <a class="header-anchor" href="#整理说明" aria-label="Permalink to &quot;整理说明&quot;">​</a></h3><p>本页按五份整理：</p><ol><li>林中相遇、身份询问、初次批评与追寻求教。</li><li>四类职分、四类之忧、八疵四患与受教的前提。</li><li>困厄追问、畏影恶迹与修身守真。</li><li>精诚、礼俗、人事应用与受业辞别。</li><li>子路质疑、精诚谦下与尊贤尊道。</li></ol><blockquote><p>第二节（四类职分·八疵四患）为后补：原稿第一、三节之间曾跳空，现依所提供文本补入，五节次序与原文吻合。</p></blockquote><p>本栏目不重复全篇原文，主要统合问答的递进、概念的联系与阅读限度。</p><h2 id="行动线与阅读路径" tabindex="-1">行动线与阅读路径 <a class="header-anchor" href="#行动线与阅读路径" aria-label="Permalink to &quot;行动线与阅读路径&quot;">​</a></h2><h4 id="行动线-倾听、询问、追寻、受教、解释" tabindex="-1">行动线：倾听、询问、追寻、受教、解释 <a class="header-anchor" href="#行动线-倾听、询问、追寻、受教、解释" aria-label="Permalink to &quot;行动线：倾听、询问、追寻、受教、解释&quot;">​</a></h4><ol><li><strong>生活场景</strong>：孔子弦歌，弟子读书。</li><li><strong>外部询问</strong>：渔父听至曲终，问孔子的身份与所治。</li><li><strong>弟子称述</strong>：子贡以忠信、仁义、礼乐、人伦及利天下介绍孔子。</li><li><strong>位置追问</strong>：渔父问君主、辅臣之位，提出危真远道的批评。</li><li><strong>主动求教</strong>：孔子闻报，推琴而起，追至泽畔。</li><li><strong>责任与行为检验</strong>：渔父说明四类职分、八疵四患及可教条件。</li><li><strong>切身追问</strong>：孔子列举困厄，求明所失。</li><li><strong>办法检验</strong>：畏影恶迹说明重复失当办法可能加重问题。</li><li><strong>内在根据</strong>：由修身守真进入精诚及其在人事中的实现。</li><li><strong>相遇的限度</strong>：孔子请求继续受业，渔父鼓励自勉并辞别。</li><li><strong>解释受教</strong>：子路质疑恭敬，孔子以尊贤、得真与尊道作答。</li></ol><h4 id="思想线-做什么、凭什么做、怎样做、依据什么做" tabindex="-1">思想线：做什么、凭什么做、怎样做、依据什么做 <a class="header-anchor" href="#思想线-做什么、凭什么做、怎样做、依据什么做" aria-label="Permalink to &quot;思想线：做什么、凭什么做、怎样做、依据什么做&quot;">​</a></h4><p><strong>所治与目标 → 所事与所位 → 行为方式与后果 → 办法是否合宜 → 修身守真的根据 → 内容与形式 → 敬人与听学。</strong></p><p>这是一条阅读上的归纳，不是原文列出的抽象体系。</p><h4 id="四次关键追问" tabindex="-1">四次关键追问 <a class="header-anchor" href="#四次关键追问" aria-label="Permalink to &quot;四次关键追问&quot;">​</a></h4><table tabindex="0"><thead><tr><th>追问</th><th>发问者</th><th>打开的问题</th></tr></thead><tbody><tr><td>孔氏者何治也？</td><td>渔父</td><td>实践与目标</td></tr><tr><td>丘不知所失……何也？</td><td>孔子</td><td>行动与困厄</td></tr><tr><td>请问何谓真？</td><td>孔子</td><td>守真的内容</td></tr><tr><td>渔父何以得此乎！</td><td>子路</td><td>恭敬的根据与程度</td></tr></tbody></table><p>四問逐层推进。全篇不是渔父单向讲完的训辞，而是由不同人物的追问不断展开的对话。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h4 id="第一问-渔父究竟在批评孔子的什么" tabindex="-1">第一问：渔父究竟在批评孔子的什么？ <a class="header-anchor" href="#第一问-渔父究竟在批评孔子的什么" aria-label="Permalink to &quot;第一问：渔父究竟在批评孔子的什么？&quot;">​</a></h4><p><strong>不是仅凭善意、仁心或天下目标就结束判断。</strong></p><p>“仁则仁矣”先承认仁，再提出保留。后续教诲有三层：</p><ol><li><strong>职分层</strong>：广泛经营礼乐、人伦与教化，是否有相应位置与责任？</li><li><strong>行为层</strong>：介入、交往与办事，是否被迎合、私求、功名、自用或自是支配？</li><li><strong>根据层</strong>：是否不断向外经营，却未从自身修治、守真立定？</li></ol><p>因而，批评不宜概括成“所有仁义都是假”“一切公共实践都是错”。</p><p>同时，四类职分确实带有古代等级秩序的结构，不能仅用现代的责任边界观念替换其原意。它可以引出权限与分工的思考，却不能直接成为禁止无官者参与公共生活的普遍原则。</p><p>八疵四患也应分清：前面的“多事”明确针对孔子，后面的清单是自察教诲，不能将十二项逐一视为孔子的既定罪状。</p><h4 id="第二问-守真为什么不等于退出人事-礼与真又怎样相接" tabindex="-1">第二问：守真为什么不等于退出人事，礼与真又怎样相接？ <a class="header-anchor" href="#第二问-守真为什么不等于退出人事-礼与真又怎样相接" aria-label="Permalink to &quot;第二问：守真为什么不等于退出人事，礼与真又怎样相接？&quot;">​</a></h4><p><strong>真以精诚为根据，但仍须在人事中实现。</strong></p><p>真有三个层次：</p><ul><li><strong>内在</strong>：不勉强造作，情感与行动出于精诚。</li><li><strong>外在</strong>：真实会感发于外，却不以固定动作作为唯一凭证。</li><li><strong>事务</strong>：以功、乐、哀、适说明各类事务的实际内容。</li></ul><table tabindex="0"><thead><tr><th>事务</th><th>所重内容</th><th>不应替代内容的形式</th></tr></thead><tbody><tr><td>事君</td><td>功：事务成就</td><td>只有忠诚表态</td></tr><tr><td>饮酒</td><td>乐：真实欢乐</td><td>特定器具与排场</td></tr><tr><td>处丧</td><td>哀：真实哀感</td><td>仅完成礼仪</td></tr><tr><td>事亲</td><td>适：合宜照料</td><td>只守一种办法</td></tr></tbody></table><p>这说明修身守真不是取消亲属、政治、交往与丧事，而是检验人在关系中行动的根据与实现方式。</p><p>渔父批评礼俗，孔子结尾仍讲礼仁，两者有张力，也有相接的可能：</p><ul><li>形式可以表达真实。</li><li>形式也可以遮蔽、替代真实。</li><li>谦下的礼貌本身仍须精诚检验。</li></ul><p>不能简单分成“内真外假”，也不能宣布两人的礼论已经完全一致。</p><h4 id="第三问-孔子的变化写到了哪里-听学怎样才算发生转变" tabindex="-1">第三问：孔子的变化写到了哪里，听学怎样才算发生转变？ <a class="header-anchor" href="#第三问-孔子的变化写到了哪里-听学怎样才算发生转变" aria-label="Permalink to &quot;第三问：孔子的变化写到了哪里，听学怎样才算发生转变？&quot;">​</a></h4><p><strong>故事写出求教、追问与敬人根据的说明，没有写出全面完成修养。</strong></p><p>孔子的角色依次变化：</p><p><strong>被评论者 → 求教者 → 解释者。</strong></p><p>这使本篇不同于单纯的斥孔故事。孔子不仅被批评，也主动寻找批评者、追问核心概念，并向弟子说明何以敬重有所得者。</p><p>听学仍须区分三层：</p><table tabindex="0"><thead><tr><th>层次</th><th>所需发生的事</th></tr></thead><tbody><tr><td>听见</td><td>接触言语与不同判断</td></tr><tr><td>理解</td><td>明白所指，不只记住词句</td></tr><tr><td>改变</td><td>修正原有办法与评价尺度</td></tr></tbody></table><p>恭敬不是无用，但不自动完成理解；久学也不自动保证可改变。</p><p>渔父离去，没有明确判定孔子完全不可教，也没有承诺继续授业。可从结构上理解为所学仍待自身实践，但不补写成渔父刻意安排的教学考验。</p><h2 id="阅读辨析与疑难校正" tabindex="-1">阅读辨析与疑难校正 <a class="header-anchor" href="#阅读辨析与疑难校正" aria-label="Permalink to &quot;阅读辨析与疑难校正&quot;">​</a></h2><h4 id="人我后果-扰人也可能伤身" tabindex="-1">人我后果：扰人也可能伤身 <a class="header-anchor" href="#人我后果-扰人也可能伤身" aria-label="Permalink to &quot;人我后果：扰人也可能伤身&quot;">​</a></h4><blockquote><p>外以乱人，内以伤身。</p></blockquote><p>八疵不只涉及私人品格，也进入事务与关系，造成干扰、误导、毁损、离间和暗取。</p><p>这些行为可能反过来增加自身牵累、损害信任。保身之说并不只是忽略他人、退回个人安全。</p><p>不过，各类后果不必机械地一一对应，也不是现实中的必然报应公式。</p><h4 id="畏影恶迹-检验办法-不把一切失败归为投入不足" tabindex="-1">畏影恶迹：检验办法，不把一切失败归为投入不足 <a class="header-anchor" href="#畏影恶迹-检验办法-不把一切失败归为投入不足" aria-label="Permalink to &quot;畏影恶迹：检验办法，不把一切失败归为投入不足&quot;">​</a></h4><p><strong>想摆脱影迹 → 选择奔跑 → 脚印增加、影子仍在 → 误以为速度不足 → 继续加力 → 耗尽自身。</strong></p><p>譬喻中的核心，是办法本身延续或制造问题。</p><p>但它既不证明所有问题都应静止不动，也不证明孔子的全部困厄都由自己造成。自我检省与外部责任可以同时存在。</p><h4 id="职分与尊贤-责任分配不同于价值判断" tabindex="-1">职分与尊贤：责任分配不同于价值判断 <a class="header-anchor" href="#职分与尊贤-责任分配不同于价值判断" aria-label="Permalink to &quot;职分与尊贤：责任分配不同于价值判断&quot;">​</a></h4><table tabindex="0"><thead><tr><th>职分之问</th><th>尊贤之问</th></tr></thead><tbody><tr><td>谁承担什么事务？</td><td>谁值得倾听与尊重？</td></tr><tr><td>是否有相应责任与边界？</td><td>是否有真实所得？</td></tr><tr><td>是否侵越他人的所事？</td><td>是否因身份而忽略他人？</td></tr></tbody></table><p>没有显赫官位，不等于没有值得学习的所得。值得尊敬，也不意味着可以取消责任、权限与边界。</p><h4 id="八疵与四患-相关而非互斥的清单" tabindex="-1">八疵与四患：相关而非互斥的清单 <a class="header-anchor" href="#八疵与四患-相关而非互斥的清单" aria-label="Permalink to &quot;八疵与四患：相关而非互斥的清单&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类别</th><th>名称</th><th>较多涉及</th></tr></thead><tbody><tr><td>八疵</td><td>总、佞、谄、谀、谗、贼、慝、险</td><td>介入、迎合、毁损关系与暗取</td></tr><tr><td>四患</td><td>叨、贪、很、矜</td><td>功名、自用、拒谏与自是</td></tr></tbody></table><p>两组共同检验行动怎样失去合宜的边界与判断，但不是严格互斥的分类，也不宜用作给人物贴标签的工具。</p><h2 id="与《盗跖》《说剑》对读" tabindex="-1">与《盗跖》《说剑》对读 <a class="header-anchor" href="#与《盗跖》《说剑》对读" aria-label="Permalink to &quot;与《盗跖》《说剑》对读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>比较项</th><th>《盗跖》第一场</th><th>《说剑》</th><th>《渔父》</th></tr></thead><tbody><tr><td>问题入口</td><td>教化是否合宜，称誉是否巧伪</td><td>国君喜好造成死伤与国衰</td><td>仁心与教化是否仍可能危真</td></tr><tr><td>对话方向</td><td>孔子往说，盗跖反击</td><td>庄子受托，改变赵王尺度</td><td>渔父评论，孔子追寻求教</td></tr><tr><td>检验尺度</td><td>圣贤名号与实际行为</td><td>杀伤、观赏与国事功用</td><td>职分、精诚、形式与实际内容</td></tr><tr><td>结尾限度</td><td>孔子受挫离去</td><td>表现改变，仍有死亡问题</td><td>解释敬道，长期践行未展开</td></tr></tbody></table><p>三篇共同提示：名声、善意、尊贵身份与表面形式，都不能单独结束判断。</p><p>但它们不是同一套答案：《盗跖》呈现强烈价值冲突，《说剑》重排身份与功用的尺度，《渔父》进一步转向精诚、修身与可受教性。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><blockquote><p>以下是现代引申，不直接等同于原文确定含义，也不将古代等级职分照搬为现代制度原则。</p></blockquote><h4 id="有善意-还要检验介入方式" tabindex="-1">有善意，还要检验介入方式 <a class="header-anchor" href="#有善意-还要检验介入方式" aria-label="Permalink to &quot;有善意，还要检验介入方式&quot;">​</a></h4><ul><li>对方是否需要、愿意接受这份帮助？</li><li>是否明确责任、权限与能力范围？</li><li>是否只是自己觉得应该，而没有听取反馈？</li><li>是否扰乱他人的事务，也反过来耗损自身？</li></ul><p>承认边界不等于冷漠。必要的帮助、公共表达与正当责任仍须按具体情境判断。</p><h4 id="不奏效时-检验办法而不只增加投入" tabindex="-1">不奏效时，检验办法而不只增加投入 <a class="header-anchor" href="#不奏效时-检验办法而不只增加投入" aria-label="Permalink to &quot;不奏效时，检验办法而不只增加投入&quot;">​</a></h4><ul><li>原办法是否在制造新的负担？</li><li>是否把坚持本身当成正确的证明？</li><li>是否需要调整条件、分工、资源或行动方式？</li><li>哪些投入仍然有效，哪些追加可以停止？</li></ul><p>不必一概停止努力，而应辨认努力所依凭的办法。</p><h4 id="真诚不只靠自我声明" tabindex="-1">真诚不只靠自我声明 <a class="header-anchor" href="#真诚不只靠自我声明" aria-label="Permalink to &quot;真诚不只靠自我声明&quot;">​</a></h4><ul><li>表态是否对应行动？</li><li>行动是否实现应有内容？</li><li>是否愿意听取当事人的反馈？</li><li>能否承认“出发点虽好，方式仍可能失当”？</li></ul><p>以事亲为例，照料是否合宜比做足孝顺的样子更值得检验。但不能仅凭单一结果判断一个人全部的真诚。</p><h4 id="不以固定形式裁定情感" tabindex="-1">不以固定形式裁定情感 <a class="header-anchor" href="#不以固定形式裁定情感" aria-label="Permalink to &quot;不以固定形式裁定情感&quot;">​</a></h4><p>有人悲伤而沉默，有人亲近却不善表达。哭声、笑容与仪式都不是唯一凭证。</p><p>同时，不能以“真实表达”为由认可伤害他人的行为。情感真实性与表达合宜性仍是不同问题。</p><h4 id="尊敬超出身份-也不取消判断" tabindex="-1">尊敬超出身份，也不取消判断 <a class="header-anchor" href="#尊敬超出身份-也不取消判断" aria-label="Permalink to &quot;尊敬超出身份，也不取消判断&quot;">​</a></h4><p>值得学习的所得可能来自没有显赫职位的人。礼貌可以表达真实敬重，但也可能成为自我展示。</p><p>尊重他人，不等于不经检验接受其所有主张；求教也不等于建立长期依附关系。</p><h4 id="学习落实在可纠正性上" tabindex="-1">学习落实在可纠正性上 <a class="header-anchor" href="#学习落实在可纠正性上" aria-label="Permalink to &quot;学习落实在可纠正性上&quot;">​</a></h4><ul><li>见过能否更改？</li><li>闻谏能否检察？</li><li>不同于己的人有善处，能否承认？</li><li>学习经验是否帮助理解，还是成为拒绝新理解的理由？</li></ul><p>“可教”不仅是能记住更多概念，也涉及能否改变原有办法与尺度。</p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关键词</th><th>阅读定位</th><th>核心问题</th></tr></thead><tbody><tr><td>所治</td><td>第一节·询问身份与子贡述志</td><td>实际致力于什么？</td></tr><tr><td>所事与所位</td><td>第一节·追问位置；第二节·四类职分</td><td>事务与责任如何相称？</td></tr><tr><td>仁则仁矣</td><td>第一节·初次批评</td><td>仁心为何仍须接受检验？</td></tr><tr><td>危真、远道</td><td>第一节·初次批评</td><td>外在经营会否损害自身根据？</td></tr><tr><td>四者自正、无所陵</td><td>第二节·职分说明</td><td>如何承担事务而不任意侵越？</td></tr><tr><td>八疵</td><td>第二节·行为清单</td><td>介入、言语与交往怎样失当？</td></tr><tr><td>四患</td><td>第二节·办事清单</td><td>功名、自用、拒谏与自是怎样发生？</td></tr><tr><td>可教</td><td>第二节·受教条件</td><td>能否检省并改变？</td></tr><tr><td>所失、四谤</td><td>第三节·困厄追问</td><td>如何理解自身行动与遭遇？</td></tr><tr><td>畏影恶迹</td><td>第三节·譬喻</td><td>办法是否在延续所厌之物？</td></tr><tr><td>自以为尚迟</td><td>第三节·错误诊断</td><td>是否把失当误认成投入不足？</td></tr><tr><td>处阴、处静、息迹</td><td>第三节·改变条件</td><td>如何停止继续制造问题？</td></tr><tr><td>修身、守真</td><td>第三节·修身守真</td><td>从何处立定行动的根据？</td></tr><tr><td>还以物与人</td><td>第三节·解除包揽</td><td>哪些事务不必尽由自己揽持？</td></tr><tr><td>精诚之至</td><td>第四节·追问与定义</td><td>真究竟是什么？</td></tr><tr><td>强哭、强怒、强亲</td><td>第四节·强作与真实</td><td>动作是否有真实内容？</td></tr><tr><td>神动于外</td><td>第四节·内外关系</td><td>内在如何感发于外？</td></tr><tr><td>人理</td><td>第四节·真用于人理</td><td>真如何用于具体关系？</td></tr><tr><td>功、乐、哀、适</td><td>第四节·四类事务</td><td>事务应实现什么内容？</td></tr><tr><td>无一其迹</td><td>第四节·内容与行迹</td><td>是否拘定一种实现方式？</td></tr><tr><td>法天贵真、不拘于俗</td><td>第四节·礼俗辨析</td><td>礼俗是否压过真实？</td></tr><tr><td>可与往、受业、辞别</td><td>第四节·受业与辞别</td><td>同行有什么条件与限度？</td></tr><tr><td>难悟、难化</td><td>第三节与第五节·学习之难</td><td>听见为何不等于改变？</td></tr><tr><td>敬长、尊贤</td><td>第五节·礼仁回答</td><td>敬人凭什么？</td></tr><tr><td>下人、不精</td><td>第五节·精诚谦下</td><td>谦下是否出于真实？</td></tr><tr><td>道之所在</td><td>第五节·尊道作答</td><td>是否因无显位而忽略他人所得？</td></tr></tbody></table><h2 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>核心句</th><th>所在部分</th><th>阅读提示</th></tr></thead><tbody><tr><td>弟子读书，孔子弦歌鼓琴。</td><td>第一节</td><td>先呈现生活场景，尚未定罪</td></tr><tr><td>孔氏者何治也？</td><td>第一节</td><td>从名声转向实际所行</td></tr><tr><td>将以利天下。</td><td>第一节</td><td>弟子称述公共目标</td></tr><tr><td>仁则仁矣，恐不免其身。</td><td>第一节</td><td>承认仁心，仍检验代价</td></tr><tr><td>苦心劳形以危其真。</td><td>第一节</td><td>提出危真的核心问题</td></tr><tr><td>无所得闻至教，敢不虚心！</td><td>第一节</td><td>不以旧学拒绝受教</td></tr><tr><td>官治其职，人忧其事，乃无所陵。</td><td>第二节</td><td>责任、职分与侵越</td></tr><tr><td>外以乱人，内以伤身。</td><td>第二节</td><td>对外扰乱与对内损害相连</td></tr><tr><td>见过不更，闻谏愈甚。</td><td>第二节</td><td>拒绝纠正使问题加重</td></tr><tr><td>不同于己，虽善不善。</td><td>第二节</td><td>以己替代善否判断</td></tr><tr><td>能去八疵，无行四患，而始可教已。</td><td>第二节</td><td>愿听之外，还须可改变</td></tr><tr><td>丘不知所失。</td><td>第三节</td><td>困厄成为切身追问</td></tr><tr><td>举足愈数而迹愈多。</td><td>第三节</td><td>办法可能制造所厌之物</td></tr><tr><td>自以为尚迟。</td><td>第三节</td><td>错将办法失当归为用力不足</td></tr><tr><td>处阴以休影，处静以息迹。</td><td>第三节</td><td>改变条件，停止追加</td></tr><tr><td>谨修而身，慎守其真。</td><td>第三节</td><td>转回自身根据</td></tr><tr><td>今不修之身而求之人，不亦外乎！</td><td>第三节</td><td>检省持续向外求取</td></tr><tr><td>真者，精诚之至也。</td><td>第四节</td><td>真不只是不说谎</td></tr><tr><td>真悲无声而哀，真怒未发而威，真亲未笑而和。</td><td>第四节</td><td>内容不以固定动作作凭证</td></tr><tr><td>真在内者，神动于外。</td><td>第四节</td><td>内外并非彼此隔绝</td></tr><tr><td>忠贞以功为主，饮酒以乐为主，处丧以哀为主，事亲以适为主。</td><td>第四节</td><td>真须在人事中实现</td></tr><tr><td>故圣人法天贵真，不拘于俗。</td><td>第四节</td><td>礼俗不能自动压过真实</td></tr><tr><td>子勉之，吾去子矣，吾去子矣！</td><td>第四节</td><td>相遇结束，践行仍待继续</td></tr><tr><td>渔父何以得此乎！</td><td>第五节</td><td>追问受敬的根据</td></tr><tr><td>夫遇长不敬，失礼也；见贤不尊，不仁也。</td><td>第五节</td><td>礼仁仍用于解释恭敬</td></tr><tr><td>下人不精，不得其真。</td><td>第五节</td><td>谦下的形式仍须精诚</td></tr><tr><td>故道之所在，圣人尊之。</td><td>第五节</td><td>敬重不只依据权位</td></tr><tr><td>吾敢不敬乎！</td><td>第五节</td><td>孔子说明此次相遇的意义</td></tr></tbody></table><h2 id="全篇核心总表" tabindex="-1">全篇核心总表 <a class="header-anchor" href="#全篇核心总表" aria-label="Permalink to &quot;全篇核心总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>全篇提醒</th><th>应避免的误读</th></tr></thead><tbody><tr><td>善意</td><td>仁心仍须检验方式与代价</td><td>有善意就不会失当</td></tr><tr><td>职分</td><td>事务需要责任与边界</td><td>无官者都不能关心公共生活</td></tr><tr><td>疵患</td><td>行为可能被私求、自用支配</td><td>清单全是孔子的既定罪状</td></tr><tr><td>困厄</td><td>旧办法可能加重问题</td><td>受困者应承担全部责任</td></tr><tr><td>修身</td><td>先检省自身根据</td><td>完全退出人事</td></tr><tr><td>真</td><td>精诚及其真实实现</td><td>任性、情绪强烈就是自然</td></tr><tr><td>形式</td><td>不应替代内容</td><td>所有外在表现都是假的</td></tr><tr><td>礼仁</td><td>可以表达真实敬重</td><td>前后张力已彻底解决</td></tr><tr><td>尊贤</td><td>敬重不只依据权位</td><td>有所得者可不受任何边界约束</td></tr><tr><td>学习</td><td>听见、理解、改变须区分</td><td>久学、再拜就等于已悟</td></tr><tr><td>辞别</td><td>相遇结束，实践仍待继续</td><td>已判定孔子完全不可教</td></tr><tr><td>结果</td><td>孔子说明敬道的根据</td><td>已证明全面得道</td></tr></tbody></table><h2 id="五份·一句话回顾" tabindex="-1">五份·一句话回顾 <a class="header-anchor" href="#五份·一句话回顾" aria-label="Permalink to &quot;五份·一句话回顾&quot;">​</a></h2><ol><li><strong>林中相遇</strong>：渔父先听完琴歌再发问，批评建立在询问之上，而不是路过的一句判断。</li><li><strong>四类职分</strong>：四者各安其位则治；八疵伤关系，四患坏事功，去掉才谈得上「可教」。</li><li><strong>困厄追问</strong>：孔子问「我失在哪里」，得到的回答是办法与目标冲突——不是不够用力，而是方向错了。</li><li><strong>何谓真</strong>：真不是没有说谎，而是精诚之至落实为合宜的内容与法度。</li><li><strong>子路质疑</strong>：尊贤不是放弃自持；孔子把「道」放在「位」之前，也把「可受教」留给自己。</li></ol><h2 id="一句话读懂《渔父》" tabindex="-1">一句话读懂《渔父》 <a class="header-anchor" href="#一句话读懂《渔父》" aria-label="Permalink to &quot;一句话读懂《渔父》&quot;">​</a></h2><blockquote><p><strong>「真者，精诚之至也。不精不诚，不能动人。」</strong></p></blockquote><p>《渔父》先说破：造作的悲怒亲近，形似而内不应。再说透：内在的精诚必须落成合宜的内容、法度与事理，否则只是自我感动的姿态。最后把问题交回孔子——也交回读者：我做的事是我该承担的吗？我用的办法在解决还是在加重问题？我的真诚有没有落成合宜的内容？</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><h4 id="本次实际依据" tabindex="-1">本次实际依据 <a class="header-anchor" href="#本次实际依据" aria-label="Permalink to &quot;本次实际依据&quot;">​</a></h4><ul><li>《庄子·杂篇·渔父》：以用户提供的原文为本次工作底本。</li><li>用户提供的《渔父》分段释义、思想辨析及全篇整理材料。</li><li>《盗跖》《说剑》的对读：依据本次整理材料中所提出的比较方向，不在此展开版本或历史考证。</li></ul><h4 id="后续校核可参考" tabindex="-1">后续校核可参考 <a class="header-anchor" href="#后续校核可参考" aria-label="Permalink to &quot;后续校核可参考&quot;">​</a></h4><p>以下为可用于进一步核对字词、句读与不同解释的参考书，本次未逐项核查其具体条目：</p><ul><li>郭庆藩《庄子集释》。</li><li>王先谦《庄子集解》。</li><li>陈鼓应《庄子今注今译》。</li></ul><p><strong>引用边界</strong>：本文所保留的疑难字句说明，不等于已经完成上述各书的版本对勘。人物评价、故事叙事与历史事实不能直接等同；现代启发另作引申，不作为原文确定含义。</p><h2 id="全篇最后一问" tabindex="-1">全篇最后一问 <a class="header-anchor" href="#全篇最后一问" aria-label="Permalink to &quot;全篇最后一问&quot;">​</a></h2><p>第一节先是一次批评：</p><p><strong>「仁则仁矣，恐不免其身。」</strong></p><p>末节留下对照：</p><p><strong>「见夫子未尝不分庭伉礼，夫子犹有倨敖之容。」</strong></p><p>从「被批评」到「被质疑是否真能尊贤」，中间隔着一次追上去求教。于是最后可以这样问自己：</p><p><strong>我做的事，是我该承担的吗？</strong></p><p><strong>我用的办法，是在解决还是在加重问题？</strong></p><p><strong>我表现的真诚，有没有落成合宜的内容？</strong></p><p><strong>遇到不同于自己的人，我能否承认他的善与所得？</strong></p><h2 id="全篇收束·少一点造作-多一点可受教" tabindex="-1">全篇收束·少一点造作，多一点可受教 <a class="header-anchor" href="#全篇收束·少一点造作-多一点可受教" aria-label="Permalink to &quot;全篇收束·少一点造作，多一点可受教&quot;">​</a></h2><p>《渔父》的推进，可以归结为四步：</p><ol><li>从善意与天下目标，追问所事、所位与代价。</li><li>从职分与疵患，转到行动者能否检省自己的办法。</li><li>以精诚说明真，使形式回到实际内容。</li><li>以尊贤、尊道解释恭敬，使听学超出权位与旧有成见。</li></ol><p>最值得保留的几个问题是：</p><blockquote><p>我所做的事，是否真是应由我承担的事？<br> 我所用的办法，是否正在制造自己想摆脱的问题？<br> 我所表现的真诚，是否落实为合宜的内容？<br> 遇到不同于自己的人，能否承认其善与所得？</p></blockquote><p>《渔父》不仅要求少一点造作与包揽，也要求多一点检省、精诚与真正的可受教性。</p>',114))])}}});export{F as __pageData,J as default};
